// Reviewed release source. Every summary/example is written for this catalog.
// A bibliographic/definition check is not a claim of universal effectiveness.
const s = (author, work, url) => ({ attribution: author, works: [work], sources: [{title: work, url}], status: '書誌確認済み' });
const apa = term => s('American Psychological Association', `APA Dictionary of Psychology: ${term}`, `https://dictionary.apa.org/${term}`);
const perception = s('OpenStax / Rose M. Spielmanほか', 'Psychology 2e (2020), 5.1 Sensation versus Perception', 'https://openstax.org/books/psychology-2e/pages/5-1-sensation-versus-perception');
const r = (candidate, section, title, aliases, knowledgeType, summary, relatedTheoryIds, provenance, note) => ({candidate, section, title, aliases, knowledgeType, summary, relatedTheoryIds, provenance:{...provenance,note}});
export const additions = [
  r(1,'psychology-c','サブリミナル効果',['subliminal perception','閾下知覚','サブリミナル知覚'],'phenomenon',
    '意識的には識別できないほど短時間・低強度の刺激が、条件によって後続の知覚や反応に影響する現象。閾下での処理と、意識できる刺激によるプライミングを区別する。実験では刺激の見え方を測定し、反応の小さな差を調べる。隠した広告で誰の意思でも長期間支配できるという意味ではない。広告の効果を考える際は、閾値の測定、実験条件、実生活での再現性まで確認する。',['kb_858','kb_004'],perception,'閾下知覚の存在と、強力な購買操作という俗説を分離。subliminal primingは下位の実験手続きなので正式同義語にしない。'),
  r(2,'psychology-c','信号検出理論',['signal detection theory'],'theory',
    '雑音の中で信号を見分ける判断を、感度と判定基準に分けて説明する理論。命中、見逃し、誤警報、正しい棄却を区別し、見逃しを減らす設定が誤警報を増やす場合も評価する。例えば検品で不良品を多く発見しても、正常品まで大量に除いていれば感度が高いとは限らない。注意力の良し悪しを一つの正答率だけで決めないために使える。成績は信号の出現率や損失の見積もりにも左右される。',['kb_844','kb_214'],perception,'SDTは自己決定理論と衝突するため検索補助語へ。'),
  r(3,'psychology-c','ウェーバーの法則',["Weber's law",'Weber law'],'principle',
    '刺激の違いに気づくために必要な変化量は、一定範囲では元の刺激強度に比例するという精神物理学の法則。軽い荷物には小さな増量でも気づくが、重い荷物では同じ増量が分かりにくい。弁別閾を絶対量だけでなく比率で考える手掛かりになる。値上げや音量調節の理解にも参考になるが、感覚の種類や強度の端では単純な比例が崩れる。価格への態度や満足のすべてを説明する経済法則ではない。',['kb_139','kb_401'],perception,'弁別閾は測定概念であり法則そのものの別名にはしない。'),
  r(4,'psychology-c','感覚順応',['sensory adaptation'],'phenomenon',
    '同じ刺激が続くと、その刺激に対する感覚系の反応や主観的な強さが変わる現象。部屋のにおいを入室直後ほど感じなくなることなどが例になる。変化を検出しやすくする働きがある一方、慣れた環境では刺激の存在を過小評価する可能性もある。環境確認では自分の感覚だけに頼らず、必要なら測定器や別の人の確認を使う。報酬による学習、注意の慣れ、幸福感の快楽順応とは説明の水準が異なる。',['kb_945','kb_268'],perception,'馴化は行動上の非連合学習。感覚順応と同義にしない。'),
  r(5,'psychology-c','知覚的構え',['perceptual set','知覚的セット'],'phenomenon',
    '期待や経験、現在の目的によって、ある解釈や特徴を知覚しやすくなる準備状態。誤植を含む文章でも文脈に沿った語として読める一方、探している物の形にこだわって目の前の別の形を見落とすことがある。検品や情報確認では、期待する答えを先に決めず、異なる見方で再確認するとよい。ただし期待が常に知覚を支配するわけではない。信念に合う証拠を集める確証バイアスより、知覚の解釈に焦点を当てる。',['kb_596','kb_858'],apa('perceptual-set'),'選択的知覚という広い項目を参照しつつ、期待による構えに限定して説明。'),
  r(6,'psychology-c','ゲシュタルトの群化原理',['Gestalt principles of grouping','知覚的群化'],'principle',
    '近接、類同、よい連続、閉合などの手掛かりにより、個々の要素をまとまりとして知覚する原理群。資料で近い位置にある項目は同じグループに、形の似た記号は同じ種類に見えやすい。図解や画面を作る際は、意味のまとまりと視覚的なまとまりを揃えるために使える。複数の原理が競合することもあり、これだけで最適なデザインが決まるわけではない。全体を重視する一般的な人生訓とは区別する。',['kb_450','kb_746'],s('OpenStax / Rose M. Spielmanほか','Psychology 2e, 5.6 Gestalt Principles of Perception','https://openstax.org/books/psychology-2e/pages/5-6-gestalt-principles-of-perception'),'知覚の原理群。ゲシュタルト療法とは別概念。'),
  r(7,'psychology-c','トップダウン処理・ボトムアップ処理',['top-down and bottom-up processing'],'model',
    '知覚を、既有知識や期待から解釈するトップダウンの方向と、入力された特徴から組み立てるボトムアップの方向で捉える枠組み。読みにくい文字を文脈から補うときと、未知の記号を線や形から見分けるときを比較できる。観察では先入観を点検しつつ、経験が理解を助ける面も活かす。実際の知覚は両方向が関わり、どちらかだけが正しいわけではない。経営のトップダウン・ボトムアップ方式を指す用語とは異なる。',['kb_858','kb_450'],perception,'一つの比較枠組みとして収録。片方だけの語は関連検索語にする。'),
  r(8,'psychology-c','予測符号化理論',['predictive coding'],'theory',
    '上位の処理が下位の入力を予測し、予測と実際の入力の差を使って内部モデルを更新するという説明枠組み。曖昧な図が文脈によって違って見えることを、単なる受動的な受信ではなく予測と修正の過程として考える。思い込みを点検するときは、予測に合わなかった情報にも注意を向ける手掛かりになる。ただし日常の助言は枠組みからの応用例で、脳の全機能が単一の予測算法で説明済みという意味ではない。',['kb_570','kb_450'],s('Rajesh P. N. Rao / Dana H. Ballard','Predictive coding in the visual cortex (1999)','https://pubmed.ncbi.nlm.nih.gov/10195184/'),'視覚皮質の計算モデルを起点とする。自由エネルギー原理そのものとは同義にしない。'),
  r(9,'psychology-m','注意資源理論',['capacity theory of attention','注意容量理論'],'theory',
    '複数の課題が限られた処理資源を分け合うため、同時に求められる処理量が増えると成績が下がりうるという説明。難しい文章を読みながら込み入った会話をすると、どちらかの内容を落としやすい。仕事では同時進行を当然視せず、集中を必要とする時間を分ける設計に役立つ。練習で自動化された処理や、異なる種類の資源を使う課題もあるため、すべての組合せが同じ程度に干渉するとは限らない。',['kb_493','kb_745'],s('Daniel Kahneman','Attention and Effort (1973)','https://kahneman.scholar.princeton.edu/document/4'),'単一資源説と複数資源説を混同せず、容量という説明の水準を示す。'),
  r(10,'psychology-c','アフォーダンス',['affordance'],'theory',
    '環境が、ある身体や能力をもつ行為者に対して提供する行為の可能性。腰掛けられる高さの段差は大人には座る可能性を与えても、小さな子には同じ使い方を提供しない場合がある。道具や場所を考える際、物の形だけでなく使う人との関係を見る視点になる。「押す」と書いた表示は行為を伝える手掛かりであり、可能性そのものとは区別する。望ましい行動を必ず起こさせる力や、見た目の分かりやすさだけを指す語ではない。',['kb_528','kb_178'],apa('affordance'),'J. J. Gibsonの生態学的知覚論。知覚されたアフォーダンスやシグニファイアと区別。'),
  r(14,'psychology-m','注意残余',['attention residue'],'phenomenon',
    'ある仕事から別の仕事へ移っても、直前の仕事への思考が残り、新しい仕事に注意を十分向けにくくなる現象。未完の企画を中断して会議に入ると、会議中も企画の続きが気になることが例になる。切り替え前に次に行うことを短く記録し、区切りを設けるなど、移行を設計する手掛かりになる。単に切り替えに時間がかかる現象や未完了課題の記憶優位とは焦点が異なり、残余の程度は課題や中断条件で変わる。',['kb_531','kb_493'],s('Sophie Leroy','Why is it so hard to do my work? (2009)','https://doi.org/10.1016/j.obhdp.2009.04.002'),'注意残余と一般的なマルチタスクのコストを同一視しない。'),
  r(15,'psychology-m','注意の捕捉',['attentional capture','注意捕捉'],'phenomenon',
    '現在行っている課題とは別の刺激に注意が引き寄せられる現象。読書中に突然の通知音へ目を向けるように、刺激の目立ちやすさや、自分の目標に合う特徴が関わる。集中したい場面では不要な通知を減らし、必要な警告は適切に目立たせる設計に使える。ただし目立つ物なら何でも必ず注意を奪うわけではない。注意を向ける準備、課題の負荷、学習した価値によって捕捉されやすさが変わる。',['kb_017','kb_872'],apa('attentional-capture'),'外因的刺激と目標による制御の関係は研究上の論点。'),
  r('extra-absolute','psychology-c','絶対閾',['absolute threshold','感覚閾'],'principle',
    '統制した測定条件で、刺激の存在を一定の割合、通常は半数の試行で検出できる最小の強度。音量を少しずつ変えて聞こえたかを繰り返し尋ねると、毎回必ず聞こえる境界ではなく検出確率として捉えられる。表示や警告の設計では、測定条件と利用者の違いを確認するために役立つ。疲労、雑音、期待でも結果は変わる。二つの刺激の違いを検出する弁別閾とは別で、全員共通の固定値ではない。',['kb_872'],perception,'心理物理学の測定概念。無意識の処理の有無を単独で確定する指標ではない。'),
  r('extra-attention','psychology-m','選択的注意',['selective attention'],'phenomenon',
    '同時に入る多くの情報のうち、目的に関係する対象を優先して処理する働き。騒がしい場所で相手の話へ注意を向けると、周囲の会話の内容は把握しにくくなる。会議や学習では注目すべき対象を明確にし、重要な情報が見落とされる可能性も見込んで確認を設ける。選択されなかった情報がすべて処理されないという意味ではない。注意の選択は、刺激、目標、慣れ、負荷に応じて変わる。',['kb_017','kb_872','kb_874'],apa('attention'),'注意の一般的な選択機能。非注意性盲目はその結果生じうる個別現象として区別。'),
  r('replace-16','psychology-c','心的回転',['mental rotation'],'phenomenon',
    '物体や図形の向きを頭の中で変え、同じ形かどうかを判断する心的操作。異なる角度から描かれた立体を比較する実験では、角度差が大きいほど判断時間が長くなる傾向が示された。家具の配置や図面の理解で、向きを変えた姿を想像することが身近な例になる。空間課題を考える基礎概念だが、成績は経験、方略、課題の形式で変わる。空間能力や知能全体を一つの課題で決めつける指標ではない。',['kb_450','kb_742'],s('Roger N. Shepard / Jacqueline Metzler','Mental rotation of three-dimensional objects (1971)','https://pubmed.ncbi.nlm.nih.gov/5540314/'),'追加発見候補から採用。頻度錯覚の代替。'),
  r(17,'psychology-m','スキーマ理論',['schema theory'],'theory',
    '経験から作られた知識の枠組みが、新しい情報の理解、記憶、推測を方向づけるという考え方。会議と聞けば議題や発言順を予想できるが、実際にはなかった内容まで補って思い出すこともある。学習では既に知る構造に新しい知識を結びつけ、同時にその枠に合わない事実を確かめる視点になる。知識の構造を扱う概念であり、連想の一時的な活性化を説明するプライミングや、信念を守る確証バイアスと同義ではない。',['kb_414','kb_596','kb_858'],apa('schema'),'Bartlett、Piagetらに連なる複数の用法。単一提唱者の万能理論にしない。'),
  r(18,'psychology-m','スクリプト理論',['script theory','スクリプト・スキーマ'],'theory',
    'よく経験する出来事の典型的な順序が、ひとまとまりの知識として理解や記憶を助けるという説明。飲食店で入店、注文、食事、支払いを予測できるのが例になる。初めての業務の手順を伝えるときは、相手が前提としている順序を確かめると行き違いを減らせる。実際の出来事が典型と異なると、抜けた工程を勝手に補う場合もある。一般的なスキーマのうち出来事の系列に焦点を当て、台本の読み上げ技法とは区別する。',['kb_414','kb_876'],apa('script'),'SchankとAbelsonの出来事知識に対応する用法。'),
  r(19,'psychology-m','展望記憶',['prospective memory','未来記憶'],'phenomenon',
    '将来の適切な時点で、予定していた行動を思い出して実行するための記憶。午後3時に連絡する時間ベースの予定と、相手に会ったら資料を渡す出来事ベースの予定などがある。予定を覚えているだけでは足りず、別の活動中に実行のきっかけを検出する必要がある。仕事では通知や物の配置を具体的な行動に結び付けるとよい。過去を思い出す記憶や、将来を想像することとは異なり、失敗を意欲不足だけで説明しない。',['kb_172','kb_441'],apa('prospective-memory'),'実行意図は展望記憶を支援する手法であり、同義ではない。'),
  r(20,'psychology-m','前向干渉・逆向干渉',['proactive and retroactive interference'],'phenomenon',
    '似た内容の記憶同士が競合し、学習や想起を妨げる現象。古い暗証番号が新しい番号の想起を邪魔するのが前向干渉、新しい番号の学習で古い番号を思い出しにくくなるのが逆向干渉である。似た手順を覚える際は、違いを明示し、適切な状況で取り出す練習を設ける。単に時間が経ったための忘却とは区別する。二方向を比較する一つのカードとし、どの記憶が必ず消えるかを予測する法則にはしない。',['kb_738','kb_879'],apa('interference'),'片方向の名称は全体の同義語ではなく関連検索語。'),
  r(21,'psychology-m','舌先現象',['tip-of-the-tongue phenomenon','舌端現象'],'phenomenon',
    '知っている語や名前を思い出せそうだと感じながら、今はうまく取り出せない状態。人物の職業や名前の頭文字は浮かぶのに、名前全体が出てこないことが例になる。情報が失われた場合と、一時的な検索の失敗を分けて考える手掛かりになる。少し時間を置く、関連する文脈を確かめるなどで思い出すこともあるが、必ず解決する方法ではない。日常で時々起きる現象だけを根拠に、認知機能の病気や知識不足を判断しない。',['kb_877','kb_414'],apa('tip-of-the-tongue-phenomenon'),'TOTは短い略称なので補助語へ。'),
  r(22,'psychology-m','フラッシュバルブ記憶',['flashbulb memory'],'phenomenon',
    '驚きや重大さを伴う出来事の知らせを受けた状況について、鮮明に覚えていると感じる記憶。大きな出来事をどこで誰から聞いたかが詳しく浮かぶことなどが例になる。鮮明さや確信は正確さと同じではなく、後の情報や反復によって内容が変わる場合もある。証言や会話では「はっきり覚えている」という感覚だけで確認を省かず、記録と照らす。写真のような完全保存を意味せず、すべての強い記憶がこの種類になるわけでもない。',['kb_876','kb_877'],apa('flashbulb-memory'),'BrownとKulikの研究に由来。鮮明さと保持精度を明確に分離。'),
  r(23,'psychology-m','回想バンプ',['reminiscence bump'],'phenomenon',
    '中高年以降に人生を振り返った際、青年期から成人初期の出来事が相対的に多く想起される傾向。昔の友人との出会いや進学の記憶が、他の時期より多く浮かぶことなどが例になる。人生の語りや世代間の対話では、思い出されやすさと当時の出来事の客観的重要性を分けて考えられる。山が現れる年齢や大きさは、質問、手掛かり、文化などで変わる。人生の最良期が若い時期に固定されるという主張ではない。',['kb_246','kb_909'],s('David C. Rubin / Matthew D. Schulkind','The distribution of autobiographical memories across the lifespan (1997)','https://pubmed.ncbi.nlm.nih.gov/9421572/'),'人生全体にわたる想起分布の研究。単なる懐古や初頭効果とは区別。'),
  r(24,'psychology-m','偽記憶',['false memory','虚記憶'],'phenomenon',
    '実際には起きなかった出来事を覚えていると感じたり、起きた出来事を実際と異なる形で思い出したりすること。会話で聞いた内容を、自分が直接見たこととして思い出す場合などがある。記憶は再構成されるため、誤情報、連想、出所の取り違えなど複数の経路が関わる。聞き取りでは誘導的な質問を避け、独立した記録を照合する。記憶違いと意図的な嘘は別であり、この概念だけで個別の記憶が真か偽かを決められない。',['kb_876','kb_877','kb_831'],s('OpenStax / Rose M. Spielmanほか','Psychology 2e, 8.3 Problems with Memory','https://openstax.org/books/psychology-2e/pages/8-3-problems-with-memory'),'誤情報効果は生成経路の一つ。偽記憶はより広い現象で別カード。'),
  r(26,'psychology-m','プルースト効果',['Proust phenomenon','Proust effect','嗅覚誘発自伝的記憶'],'phenomenon',
    'においが、個人的な過去の出来事と当時の感情を呼び起こす現象を指す通称。昔使った石けんの香りから、家族との生活場面が急に浮かぶような例で理解できる。においと言葉や写真では、想起される記憶の感情的性質が異なる場合がある。思い出を語るきっかけにはなるが、香りが誰にでも良い記憶を作る、記憶を正確に復元するという効果ではない。不快な経験を思い出す人もいるため、利用時は本人の反応を優先する。',['kb_826','kb_878'],s('Rachel S. Herz / Jonathan W. Schooler','A naturalistic study of autobiographical memories evoked by olfactory and visual cues (2002)','https://pubmed.ncbi.nlm.nih.gov/11868193/'),'嗅覚で誘発される自伝的記憶に限定。医療上の改善効果は主張しない。'),
  r(27,'psychology-c','二重過程理論',['dual-process theory','dual-process theories'],'theory',
    '推論や判断を、自律的で素早い処理と、作業記憶を使う検討的な処理の違いから説明する理論群。見慣れた答えを即座に選ぶときと、その答えを計算や規則で点検するときを比較できる。重要な判断では直感の根拠を確認する時間を設ける手掛かりになる。脳に二つの独立した箱があるという主張ではなく、速さだけで処理を判別できるわけでもない。直感が常に誤りで、熟考が常に正しいという意味でもない。',['kb_754','kb_430','kb_745'],s('Jonathan St B. T. Evans / Keith E. Stanovich','Dual-Process Theories of Higher Cognition (2013)','https://doi.org/10.1177/1745691612460685'),'単一理論ではなく理論群。喪失の二重過程モデルとは異なる。'),
  r(28,'psychology-c','属性置換',['attribute substitution'],'heuristic',
    '難しい問いを判断するとき、答えやすい別の属性で知らずに置き換えて答えること。「この計画は成功するか」を「担当者は好ましいか」で判断する場合などがある。利用可能な情報が、本来求められた評価を代用してしまう仕組みとして考える。判断を点検するときは、今評価している属性と、本来の問いを別々に書き出す。すべての簡便な判断が属性置換とは限らず、適切な代替指標が役立つ場合もある。好感そのものや確証バイアスと同義ではない。',['kb_003','kb_430','kb_597'],s('Daniel Kahneman / Shane Frederick','属性置換のモデル；Kahneman, Maps of Bounded Rationality (2003)','https://kahneman.scholar.princeton.edu/document/8'),'容易な属性への置換という機序を収録。'),
  r(29,'psychology-c','信念バイアス',['belief bias'],'phenomenon',
    '結論がもっともらしいかどうかによって、論証の論理的な妥当性の判断が影響される傾向。日常的に正しそうな結論だと、前提からその結論が導けていなくても受け入れやすくなる。議論を読む際は、結論への賛否と、前提を仮に認めたとき推論が成立するかを分けて確かめる。信念に合う情報を探す確証バイアスより、提示済みの推論の評価に焦点を当てる。内容への知識が常に無益という意味ではなく、形式と事実確認の両方が必要である。',['kb_596','kb_929'],s('Jonathan St B. T. Evans / Julie L. Barston / Paul Pollard','On the conflict between logic and belief in syllogistic reasoning (1983)','https://doi.org/10.3758/BF03196976'),'論理的妥当性と内容の信じやすさの実験的対立。'),
  r(31,'psychology-c','認知欲求',['need for cognition'],'phenomenon',
    '努力を要する思考に取り組み、それを楽しむ傾向の個人差。複雑な問題の理由を調べることを好む人と、要点だけを早く知りたい人の違いなどに現れる。説明を作る際は、根拠や比較を求める相手に詳細を用意するなど、関心に応じた伝え方を考えられる。ただし知能や知識量そのものを測る概念ではなく、疲労や関心によっても取り組み方は変わる。結論を早く確定したい認知的閉鎖欲求とは異なる。',['kb_881'],apa('need-for-cognition'),'CacioppoとPettyらの個人差構成概念。能力や優劣の診断にしない。'),
  r(34,'psychology-c','イデオモーター効果',['ideomotor effect','観念運動'],'phenomenon',
    '動作についての考えや期待が、意図していると自覚しにくい小さな運動に結び付く現象。手に持った振り子が、予想した方向へわずかに動くことなどが例になる。本人が動かした感覚を持たないことは、外部の不思議な力が働いた証拠にはならない。体験を検討する際は、期待や微細な身体運動を分けて確かめる。行動の模倣や広い社会的プライミングと同義ではなく、あらゆる考えがそのまま実行されるという主張でもない。',['kb_391','kb_231'],apa('ideomotor-activity'),'観念と微細な運動の関係。念力等を支持する概念として扱わない。'),
  r(36,'psychology-e','感情調整プロセスモデル',['process model of emotion regulation'],'model',
    '感情が生じて表れるまでの過程に沿って、状況選択、状況修正、注意の配分、認知の変化、反応の調整を区別するモデル。苦手な会議では、準備や席の選び方を変えることと、会議中に表情を抑えることは介入する段階が違う。感情を我慢する以外の選択肢を探すために使える。ただし各方略が常に良い・悪いわけではなく、目的や対人状況に応じて機能が変わる。感情を完全に消す方法を示すものではない。',['kb_229','kb_227','kb_224'],s('James J. Gross','The Emerging Field of Emotion Regulation (1998)','https://doi.org/10.1037/1089-2680.2.3.271'),'調整の時点を整理するモデル。個別技法の効果保証ではない。'),
  r(39,'psychology-e','情動粒度',['emotional granularity','emotion differentiation','感情粒度'],'phenomenon',
    '自分の感情経験を、単に良い・悪いだけでなく、焦り、落胆、怒りなどとして細かく区別する程度。仕事で同じ「つらい」でも、期限への焦りか、扱われ方への怒りかで必要な対応は違う。感情を記録するとき、状況に合う言葉を探すための視点になる。研究では日々の報告のパターンなどから測り、語彙の多さだけと同一視しない。精神的健康との関連はあるが、言葉を増やせば必ず症状が改善するという因果の保証ではない。',['kb_227','kb_229'],s('Katie Hoemann / Lisa Feldman Barrett / Karen S. Quigley','Emotional Granularity Increases With Intensive Ambulatory Assessment (2021)','https://pubmed.ncbi.nlm.nih.gov/34393942/'),'構成概念と関連の確認。介入の万能な効能にしない。'),
  r(40,'psychology-e','感情構成理論',['theory of constructed emotion','構成主義的感情理論'],'theory',
    '感情を、身体内部の感覚、過去の経験、概念、状況に基づいて脳が構成する経験として捉える理論。同じ動悸でも、発表前には不安、競技前には高揚として経験することを考える枠組みになる。自分の感情の意味を考える際、身体と文脈の両方に目を向けられる。ただし感情が好きに選べる、身体反応が存在しないという意味ではない。基本情動説などと議論が続く理論であり、すべての感情研究が合意した最終説明ではない。',['kb_885','kb_886','kb_905'],s('Lisa Feldman Barrett','The theory of constructed emotion (2017)','https://doi.org/10.1093/scan/nsw154'),'感情の分類・生成についての理論的立場。確定した唯一の機序とはしない。'),
  r(42,'psychology-e','社会的評価不安',['social-evaluative anxiety'],'phenomenon',
    '他者からどう評価されるかへの心配や、否定的に見られることへの不安。発表で内容より失敗の印象ばかり気になり、質問を避けることなどが例になる。行動を振り返るとき、実際の評価、予測した評価、その予測から取った回避行動を分けて整理できる。社会的状況の不快感や否定的評価への恐れを測る研究があるが、これだけで病気を診断する概念ではない。程度や生活上の影響は人によって異なり、現実の不公正な評価環境も見落とさない。',['kb_232','kb_207','kb_816'],s('David Watson / Ronald Friend','Measurement of social-evaluative anxiety (1969)','https://pubmed.ncbi.nlm.nih.gov/5810590/'),'fear of negative evaluationは測定上の側面であり、全体の厳密な同義語にしない。'),
  r(43,'psychology-s','自尊心の随伴性',['contingencies of self-worth','自己価値の随伴性'],'theory',
    '自分の価値が、他者の承認、競争での成功、外見など特定の領域の結果にどれほど依存しているかを捉える枠組み。仕事の失敗を能力の一部への評価でなく「自分には価値がない」と受け止める場合などが例になる。自尊心の高低だけでなく、何に支えられ、どんな出来事で揺れるかを見直す手掛かりになる。達成に価値を置くこと自体が必ず有害なわけではない。依存する領域や、その領域での経験によって影響は変わる。',['kb_257','kb_815','kb_264'],s('Jennifer Crocker / Connie T. Wolfe','Contingencies of self-worth (2001)','https://pubmed.ncbi.nlm.nih.gov/11488379/'),'自尊心の水準や不安定さそのものとは分ける。'),
  r(44,'psychology-s','多次元的完璧主義',['multidimensional perfectionism'],'model',
    '完璧さへの要求を一種類とせず、自分への要求、他者への要求、他者から要求されている感覚などに分けて捉える枠組み。資料を何度も直す人でも、自分の基準の高さと「少しでも誤ると見放される」という受け止めでは対応が違う。基準、失敗への反応、対人期待を分けて振り返るために使える。異なる研究者の尺度には別の次元構成もあり、単一の分類で人を断定しない。丁寧さや高い目標がすべて問題だという意味ではない。',['kb_727','kb_728','kb_264'],s('Paul L. Hewitt / Gordon L. Flett','Perfectionism in the self and social contexts (1991)','https://pubmed.ncbi.nlm.nih.gov/2027080/'),'Hewitt–Flettの三次元を例示。Frost尺度との同一視を避ける。'),
  r(45,'psychology-s','達成動機理論',['achievement motivation theory'],'theory',
    '優れた基準に照らして成功したい動機と、失敗を避けたい動機が、挑戦や課題選択にどう関わるかを説明する理論群。成功を試したい人が適度に難しい課題を選ぶ一方、失敗を強く恐れる人が極端に容易な課題へ寄る場合などを考える。目標設定では、難度だけでなく成功の見込みや失敗の意味づけを確かめる。すべての行動を競争心で説明するものではなく、動機、状況、文化、使うモデルによって予測は異なる。',['kb_750','kb_187','kb_728'],s('John W. Atkinson','Motivational determinants of risk-taking behavior (1957)','https://doi.org/10.1037/h0043445'),'Atkinsonの成功追求と失敗回避を中心に説明。期待価値一般と同義にしない。'),
  r(48,'psychology-v','道徳基盤理論',['moral foundations theory'],'theory',
    '道徳判断の違いを、ケア、公正、忠誠、権威、神聖など複数の関心の重みから説明する理論。ある提案を一方は公平さ、他方は共同体の秩序から評価すると、同じ結論を求めても対話が噛み合わない場合がある。反対意見を悪意と決めず、何を守りたいのかを聞く視点になる。基盤の数や測定、文化への一般化には議論があり、人を固定した政治的型へ分ける道具ではない。価値の違いを説明することと、その行為を倫理的に正当化することも別である。',['kb_058','kb_927'],s('Jonathan Haidt / Jesse Graham / Craig Josephほか','Moral Foundations Theory（研究者の公式解説）','https://moralfoundations.org/'),'基盤の構成は改訂されている。特定の個人・文化の診断に使わない。'),
  r(49,'psychology-v','道徳的切り離し',['moral disengagement','道徳的不活性化'],'theory',
    '通常は働く道徳的な自己抑制を、正当化や責任の分散、被害の軽視などで外してしまう過程。相手を傷つける言動でも「会社のため」「皆がやっている」と説明すると、自分を責めずに続けられる場合がある。組織や日常の判断では、目的の説明と実際の被害、誰が決めたかを分けて確認する手掛かりになる。本人に罪悪感がないことを、被害がない証拠にしない。違反を必ず生む性格特性や、単なる認知的不協和の別名ではない。',['kb_265','kb_073','kb_883'],s('Albert Bandura','Moral disengagement in the perpetration of inhumanities (1999)','https://pubmed.ncbi.nlm.nih.gov/15661671/'),'責任転嫁、婉曲表現、非人間化などの過程を扱う。'),
  r(50,'psychology-v','ルーピング効果',['looping effect','人間種のルーピング効果'],'theory',
    '人を分類する概念が当事者の自己理解や行動を変え、その変化が分類自体の理解や運用へ戻るという相互作用。ある集団に名称が与えられると、当事者がそれに応答し、分類を研究・管理する側も定義を修正する場合がある。診断名や人物像を扱うとき、分類を受ける人の反応まで含めて考える視点になる。期待が現実になる自己成就予言と重なる面はあるが、分類と人が共に変わる過程に焦点がある。あらゆる分類で同じ影響が起きるとは限らない。',['kb_473','kb_246'],s('Ian Hacking','The looping effects of human kinds, Causal Cognition (1995/1996参照版)','https://doi.org/10.1093/acprof:oso/9780198524021.003.0012'),'社会科学の分類と分類される人の相互作用。自己成就予言の同義語ではない。'),
  r(51,'psychology-v','ラベリング理論',['labeling theory','labelling theory'],'theory',
    'ある行為や人が逸脱と名付けられ、周囲からそう扱われる過程が、その後の立場や自己理解、行動に影響することに注目する社会学の理論。失敗した新人を「問題のある人」と呼び続けると、学ぶ機会や参加が制限される場合などを考えられる。行為の評価と、人の全体への固定した名付けを分ける視点になる。ラベルだけが逸脱の原因という主張ではなく、実際の行為や環境条件も必要である。感情に名前を付ける感情ラベリングとは別概念。',['kb_473','kb_470','kb_246'],s('Howard S. Becker','Outsiders (1963；出版社の参照版)','https://www.simonandschuster.com/books/Outsiders/Howard-S-Becker/9781982106225'),'社会的反応への着目。Edwin Lemert等にも先行的貢献があり、Becker単独の発明としない。'),
  r(52,'psychology-v','スティグマ',['stigma','社会的烙印'],'phenomenon',
    'ある属性が社会的に否定的な意味と結び付き、その人全体への評価や扱いを不利にすること。病歴や出自を知っただけで能力まで低く見積もる場合などがある。個人の思い込みだけでなく、情報の管理、関係、機会へのアクセスまで含めて理解する。対人場面では必要な情報と偏見を分け、本人の開示の意思を尊重する。属性そのものが本質的に劣っているという意味ではなく、文化や制度、状況によって何が不名誉とされるかは変わる。',['kb_470','kb_927','kb_731'],s('Erving Goffman','Stigma: Notes on the Management of Spoiled Identity (1963)','https://www.simonandschuster.com/books/Stigma/Erving-Goffman/9781439188330'),'社会関係上の評価として扱い、対象者の欠陥という説明を避ける。'),
  r(53,'psychology-v','トマスの定理',["Thomas theorem",'トーマスの定理'],'principle',
    '人々がある状況を現実だと定義すれば、その定義に基づいた行動は現実の結果をもつ、という社会学の命題。実際には起きていない不足の噂でも、人々が買いだめすれば店頭の不足につながる場合がある。事実を確かめるだけでなく、どのように状況が理解され、行動が変わるかを見る手掛かりになる。思えば何でも実現するという法則ではなく、誤った認識が常に自らを実現するとも限らない。自己成就予言より広い、状況の定義と結果の関係を扱う。',['kb_473','kb_106'],s('William I. Thomas / Dorothy Swaine Thomas','The Child in America (1928), p.572','https://archive.org/details/childinamerica00thom/page/572/mode/2up'),'原著の命題。心理的な願望実現の法則と混同しない。'),
  r(54,'psychology-v','象徴的相互作用論',['symbolic interactionism'],'theory',
    '人は物事がもつ意味に基づいて行動し、その意味は他者との相互作用や解釈を通して作られ、変わると捉える立場。会議での沈黙が、ある職場では同意、別の職場では慎重な検討と理解されることなどが例になる。行き違いを考える際、行動だけでなく当事者がそこに与えた意味を確かめる視点になる。すべての意味が自由に選べるわけではなく、制度や力関係の影響もある。個別の心理効果や会話の手順ではなく、社会を理解する理論的視角である。',['kb_434','kb_111','kb_942'],s('Herbert Blumer','Symbolic Interactionism: Perspective and Method (1969)','https://www.ucpress.edu/books/symbolic-interactionism/paper'),'意味、社会的相互作用、解釈という三つの前提を中心に説明。'),
  r(55,'psychology-v','社会的表象理論',['social representations theory'],'theory',
    '集団の中で共有される知識やイメージが、身近でない事象を理解し、語り、行動する枠組みになると捉える理論。新しい技術が「便利な道具」や「脅威」として日常会話に取り込まれていく過程などを考える。言葉を伝えるときは、相手の集団でその対象がどう理解されているかを確かめる手掛かりになる。全員が同じ意見をもつという意味ではなく、表象は対話や対立を通して変わる。多数派への同調や単なるステレオタイプとは説明対象が異なる。',['kb_455','kb_927','kb_942'],s('Serge Moscovici；Gordon Sammutほか編（参照資料）','The Cambridge Handbook of Social Representations (2015)','https://assets.cambridge.org/97811070/42001/excerpt/9781107042001_excerpt.pdf'),'日常知識の社会的生成という射程。個別効果の強さを保証しない。'),
  r(56,'psychology-v','道徳的パニック',['moral panic','モラル・パニック'],'theory',
    'ある人々や出来事が社会の価値を脅かすものとして描かれ、報道や社会的反応によって懸念や統制要求が急激に高まる過程を捉える社会学的概念。少数の事例から特定集団全体が危険だと語られる場合などを分析できる。情報を読む際は、実際の発生頻度、被害、報道の規模を別々に確認する。懸念の存在だけで「パニック」と決めつけず、反応が不釣り合いかを資料で検討する必要がある。実在する被害を否定するための言葉ではない。',['kb_106','kb_597','kb_927'],s('Stanley Cohen','Folk Devils and Moral Panics (1972；参照版)','https://www.routledge.com/Folk-Devils-and-Moral-Panics-1st-Edition/Cohen/p/book/9780415610162'),'社会的反応を分析する概念。誰かの不安を病理化する名称ではない。'),
  r(57,'psychology-v','他者化',['othering'],'thought',
    'ある人々を「私たち」とは本質的に異なる存在として描き、所属や権利、共感の範囲から外す過程。所属部署や出自の違いから「彼らは分かり合えない」と一括りにすると、個々の事情を聞く機会が失われる。対話では集団名による説明と、実際の行為や必要を分けて確かめる視点になる。単に違いを認めることや個人的に距離を置くことのすべてを指すわけではない。制度、権力、資源配分も含む概念であり、個人の好悪だけでは説明できない。',['kb_058','kb_485','kb_470'],s('john a. powell / Stephen Menendian','The Problem of Othering: Towards Inclusiveness and Belonging (2016)','https://www.otheringandbelonging.org/wp-content/uploads/2016/07/OtheringAndBelonging_Issue1.pdf'),'確立した批判的・社会的概念として収録。独立した実験効果という名称を付けない。'),
  r(58,'psychology-v','共有現実理論',['shared reality theory'],'theory',
    'ある対象について、自分と他者の内的な理解や感情が共通していると感じる経験に注目する理論。出来事を話し「同じように見ていた」と感じることで、自分の解釈への確信が支えられる場合などがある。対話では結論だけでなく、どの意味や感情を共有したのかを確かめる視点になる。表面的に同じ発言をしただけでは共有現実とは限らず、共感や共通知識とも区別される。共有によって判断が正確になる保証はなく、偏った理解が強まる場合も考慮する。',['kb_707','kb_266','kb_404'],s('Gerald Echterhoff / E. Tory Higgins / John M. Levine','Shared Reality: Experiencing Commonality With Others’ Inner States About the World (2009)','https://pubmed.ncbi.nlm.nih.gov/26162223/'),'対象についての内的状態の共通性。単なる意見一致から区別。'),
  r(59,'psychology-v','相互独立的・相互協調的自己観',['independent and interdependent self-construals'],'model',
    '自己を他者から区切られた独立した存在として捉える見方と、関係や役割の中で捉える見方を比較する枠組み。意思表示を「自分の希望を伝えること」と捉えるか、「関係の調整」と捉えるかで、同じ言動の意味が変わる場合がある。文化や職場の違いを理解するとき、自分の当然を点検する手掛かりになる。国籍で人を二分したり、一方が成熟していると評価したりしない。同じ人でも関係や場面によって、両方の見方を使いうる。',['kb_058','kb_258','kb_456'],s('Hazel R. Markus / Shinobu Kitayama','Culture and the self (1991)','https://doi.org/10.1037/0033-295X.98.2.224'),'文化的な自己の構成。単純な東西二分や性格診断にしない。'),
  r(60,'psychology-v','自己評価維持モデル',['self-evaluation maintenance model'],'model',
    '身近な人の優れた成果が自分の評価に及ぼす影響を、心理的な近さ、成績の差、その領域の自己にとっての重要性から説明するモデル。親友の得意分野を誇らしく感じても、自分の大切な仕事で追い抜かれると脅威を感じることがある。嫉妬や応援が入り交じるとき、相手への好悪だけでなく比較の領域を見直す手掛かりになる。近い人の成功を必ず妬むという法則ではない。関係や自己評価を調整する方法には個人差や状況差がある。',['kb_266','kb_122','kb_396'],apa('self-evaluation-maintenance-model'),'Abraham Tesserら。反映過程と比較過程を区別する。'),
  r(61,'psychology-v','社会的役割理論',['social role theory'],'theory',
    '性別などによる行動の違いや類似を、社会で担う役割と、その役割への期待から説明する理論。特定の人々がケアや指揮を多く担当すると、その行動が生来の性質だと見られ、役割分担が再生産される場合がある。人材配置では、観察された行動と与えられてきた機会を分けて考える。すべての差を役割だけに還元するものではなく、生物的条件と社会構造の関係も検討する。既存の役割に従うべきだという規範ではない。',['kb_927','kb_939','kb_075'],s('Alice H. Eagly / Wendy Wood','Social Role Theory（著者による章）','https://doi.org/10.4135/9781446249222.n49'),'Eaglyらの社会的役割理論。一般的な役割理論全体とは区別。'),
  r(62,'psychology-i','対人距離理論',['proxemics','プロクセミックス'],'theory',
    '対人場面で空間や距離がどう使われ、関係や文化と結び付くかを考える枠組み。初対面で近づきすぎると落ち着かない人がいる一方、同じ距離でも親密さや状況により受け止めは変わる。会話や席の配置では、相手の反応と場所の制約を確かめ、距離を調整する手掛かりになる。親密・個体・社会・公衆距離という整理は、全文化や全員に共通する厳密な物差しではない。距離だけから好意や性格を読み取らない。',['kb_037','kb_092','kb_474'],s('Edward T. Hall','The Hidden Dimension (1966；参照版)','https://www.penguinrandomhouse.com/books/73818/the-hidden-dimension-by-edward-t-hall/'),'Hallの空間利用の研究。単なる心理的な近さとは区別。'),
  r(63,'psychology-i','ジョハリの窓',['Johari window'],'model',
    '自分が知っているか、他者が知っているかの二軸で、自己理解を開放・盲点・秘密・未知の四領域に整理するモデル。自分では普通だと思う振る舞いを同僚から指摘されると、盲点を知る機会になる。振り返りでは具体的なフィードバックを求め、必要に応じて自己開示するために使える。すべてを開示するほど良いわけではなく、秘密や境界を守ることも大切である。四領域を精密に測定する診断法や、他人の内面を透視する方法ではない。',['kb_008','kb_115','kb_394'],s('Joseph Luft / Harrington Ingham；Curtin University（参照解説）','Looking through the Johari Window','https://www.curtin.edu.au/news/oasis-news/looking-through-the-johari-window/'),'教育・対人理解用モデル。自己開示を強制しない。'),
  r(64,'psychology-life','コールバーグの道徳性発達理論',["Kohlberg's theory of moral development"],'theory',
    '道徳判断を、どの結論を選ぶかだけでなく、その理由づけの発達から捉える段階理論。罰を避けるため、周囲に認められるため、原則を守るためなど、同じ行為でも説明の根拠は異なる。意見の違いを話し合う際、何を理由に判断したのかを聞く視点になる。実際の行動の善悪や人間の価値を段階で採点するものではない。文化、ジェンダー、課題の作り方、理由づけと実行の差に関する批判があり、固定した普遍的診断にはしない。',['kb_903','kb_954','kb_955'],s('Lawrence Kohlberg；OpenStax（参照教材）','Psychology 2e, 9.2 Lifespan Theories','https://openstax.org/books/psychology-2e/pages/9-2-lifespan-theories'),'道徳的推論の歴史的発達モデル。規範的な人物ランキングではない。'),
  r(65,'psychology-life','気質理論',['temperament theory'],'theory',
    '早期から見られる反応の強さや注意、自己調整などの個人差を、生物的基盤と発達・環境の相互作用から捉える理論群。新しい場所へすぐ近づく子と、様子を見てから参加する子では、安心して試せる支援も違う。本人を怠惰やわがままと決めず、反応の特徴と環境の合い方を見る手掛かりになる。気質は将来の性格や成功を固定しない。ThomasとChess、Rothbartらでモデルが異なり、特定の類型をすべての人へ当てはめない。',['kb_724','kb_914','kb_920'],s('Mary K. Rothbart / Stephan A. Ahadi / David E. Evans','Temperament and personality: origins and outcomes (2000)','https://pubmed.ncbi.nlm.nih.gov/10653510/'),'気質の反応性・調整と発達を扱い、成人性格との同一視を避ける。'),
  r(67,'psychology-life','遅延満足',['delay of gratification','満足遅延'],'phenomenon',
    '目の前の小さな報酬をすぐ受け取る代わりに、後のより大きな報酬を待つこと。今遊ぶ代わりに、準備を終えてから長く遊ぶような場面で考えられる。待てるかどうかは注意の向け方だけでなく、約束が守られる見込みや家庭・生活の条件にも左右される。実践では誘惑を見えにくくし、待つ理由と予定を明確にする。幼少期の一つの課題だけで人生の成功が決まるという解釈は不適切で、後の成績との関連には背景要因を考慮する必要がある。',['kb_175','kb_176','kb_174'],s('Walter Mischelら；Tyler W. Watts / Greg J. Duncan / Haonan Quan（再検討）','Revisiting the Marshmallow Test (2018)','https://pubmed.ncbi.nlm.nih.gov/29799765/'),'マシュマロ実験の課題名は補助語。待つ力と将来結果の因果を断定しない。'),
  r(68,'psychology-n','実行機能',['executive functions','executive function'],'model',
    '目標に沿って思考や行動を調整するための機能群。抑制、作業記憶、認知的柔軟性などを含み、必要な情報を保ちながら不要な反応を抑え、状況に応じて切り替える働きとして説明される。作業を小分けにし、手順を外に書くことは負荷を軽くする助けになる。計画が進まない理由を意志の弱さだけに求めない視点になるが、単一の能力や診断ではない。睡眠、ストレス、課題、発達段階などでも発揮のされ方が変わる。',['kb_745','kb_574','kb_577'],s('Adele Diamond','Executive functions (2013)','https://pubmed.ncbi.nlm.nih.gov/23020641/'),'複数の中核機能からなる枠組み。自己制御一般と完全同義にはしない。'),
  r(72,'behavioral-science-d','左端数字効果',['left-digit effect'],'phenomenon',
    '数値の左端の桁が変わると、実際の差以上に大きな違いとして受け止められることがある現象。例えば1,000円から999円への差を、同じ1円差の別の組合せより大きく感じる場合がある。価格を比べる際は、左端の印象だけでなく差額や総額を計算して確かめる。すべての端数価格が同じ効果をもつわけではなく、比較対象や注意の向け方で変わる。安さの印象を説明する概念であり、価格だけで品質や購入意向が決まるという法則ではない。',['kb_138','kb_137'],s('Manoj Thomas / Vicki Morwitz','Penny Wise and Pound Foolish: The Left-Digit Effect in Price Cognition (2005)','https://doi.org/10.1086/429600'),'数値認知の現象。9で終わる値付けのすべてと同義にはしない。'),
  r(73,'behavioral-science-d','貨幣錯覚',['money illusion'],'phenomenon',
    'お金の価値を判断する際、物価変動を考慮した実質額より、名目額に引きずられること。物価が給与より大きく上がっても、給与の数字が増えたため生活が豊かになったと感じる場合などがある。報酬や長期の計画を比べるとき、何がどれだけ買えるかという基準を併記する手掛かりになる。名目額を使うこと自体が誤りではなく、契約や制度には名目額が重要な場面もある。所得の変化への反応をすべて貨幣錯覚で説明しない。',['kb_137','kb_138'],s('Eldar Shafir / Peter Diamond / Amos Tversky','Money Illusion (1997)','https://doi.org/10.1162/003355397555208'),'名目と実質の区別。実質値の認識と公平感等の価値判断を分ける。'),
  r(74,'behavioral-science-d','指数成長バイアス',['exponential growth bias'],'phenomenon',
    '一定割合で増える過程を、一定量ずつ増えるように捉え、将来の増加を過小評価する傾向。毎年同じ割合で増える量は元本や基数も変わるため、最初の増加額をそのまま年数倍した予想とは違ってくる。長期の費用や累積量を考える際は、直感だけでなく表や式で複数時点を確かめる。実際の成長がいつまでも同じ割合で続くという意味ではなく、上限や条件変化も別に検討する。計算の誤りと、予測モデル自体の誤りを分ける。',['kb_575','kb_755'],s('Victor Stango / Jonathan Zinman','Exponential Growth Bias and Household Finance (2009)','https://doi.org/10.1111/j.1540-6261.2009.01518.x'),'金融研究を起点とする数理的認識の傾向。個別の投資推奨ではない。'),
  r(75,'behavioral-science-d','顕著性バイアス',['salience bias'],'phenomenon',
    '目立つ情報へ注意や重みが偏り、目立ちにくいが重要な情報が十分に考慮されない傾向。印象的な一件の苦情ばかりが会議で語られ、全体の発生率や利用者数が見落とされる場合などがある。判断では、目立つ理由と重要である理由を分け、共通の指標で候補を並べる。何が目立つかは比較状況や目的でも変わる。利用可能性ヒューリスティックと関わるが、思い出しやすさだけでなく、現在の比較で突出した属性に重みが付く点も扱う。',['kb_597','kb_236','kb_139'],s('Pedro Bordalo / Nicola Gennaioli / Andrei Shleifer','Salience Theory of Choice Under Risk (2012)','https://scholar.harvard.edu/files/shleifer/files/salience_theory_of_choice_under_risk_qje.pdf'),'顕著性の一般的な偏りと、引用した形式モデルの限定的予測を区別。'),
  r(77,'behavioral-science-d','選好逆転',['preference reversal'],'phenomenon',
    '同じ選択肢でも、選ぶ、値段を付けるなどの評価方法によって好みの順位が逆になる現象。二つのくじのうち当たりやすい方を選ぶのに、売却価格は大きな賞金の方へ高く付ける場合などが例になる。選択の理由を確認するときは、質問形式や測り方が判断を変えていないかを点検する。新しい情報や価値観の変化による当然の好みの変化とは区別する。誰にも本当の好みがないという結論ではなく、引き出し方による不整合を扱う。',['kb_756','kb_137','kb_442'],s('Sarah Lichtenstein / Paul Slovic','Reversals of preference between bids and choices in gambling decisions (1971)','https://doi.org/10.1037/h0031207'),'選択と価格付けの比較。質問形式が同等かを確認する。'),
  r(78,'behavioral-science-d','リスク感情理論',['risk-as-feelings hypothesis','risk as feelings'],'theory',
    '危険について考えた確率や結果の評価と、その瞬間に生じる恐怖や不安が食い違い、感情が行動を左右しうるという仮説。統計では低リスクと理解していても、鮮明な事故映像を見た直後は避けたくなる場合などがある。判断では計算した評価と現在の感情を別々に言葉にし、両方の情報を確かめる。感情を無視すべきという意味ではない。一般的な感情ヒューリスティックより、リスクに直面した感情と認知的評価の乖離に焦点を当てる。',['kb_430','kb_844','kb_887'],s('George Loewenstein / Elke U. Weber / Christopher K. Hsee / Ned Welch','Risk as Feelings (2001)','https://www.cmu.edu/dietrich/sds/docs/loewenstein/RiskAsFeelings.pdf'),'仮説としての位置づけ。恐怖が常に非合理とはしない。'),
  r(79,'behavioral-science-d','参照価格効果',['reference price effect'],'phenomenon',
    '提示価格を、過去の購入価格や通常価格などの比較基準に照らして評価すること。以前は高かったという表示を見ると、今の価格を割安に感じる場合などがある。買い物や見積もりの比較では、比較基準が実際の取引や必要に合っているかを確かめる。アンカリングと関連するが、価格の記憶や市場で形成した基準を含む。人によって参照価格は異なり、常に同じ値が保たれるわけではない。値引き率だけでなく支払総額と代替案を確認する。',['kb_138','kb_137','kb_761'],s('Russell S. Winer','A Reference Price Model of Brand Choice for Frequently Purchased Products (1986)','https://doi.org/10.1086/209064'),'日常的な価格判断の概念。参照点一般の正式別名にはしない。'),
  r(80,'behavioral-science-d','分割価格効果',['partitioned pricing'],'phenomenon',
    '価格を本体代と手数料などに分けて示すことで、総額の認識や購入判断が変わること。安い本体価格に送料を別記すると、総額では高くても安い印象が残る場合がある。比較するときは、必要な追加費用を含む総額を同じ条件で並べる。分割表示が常に需要を増やすとは限らず、手数料の納得感や明示の仕方でも反応は変わる。支払いを複数回に分ける分割払いとは異なり、情報の示し方と処理の問題として捉える。',['kb_137','kb_761'],s('Vicki G. Morwitz / Eric A. Greenleaf / Eric J. Johnson','Divide and Prosper: Why Firms Divide Prices Instead of Charging a Single Price (1998)','https://business.columbia.edu/faculty/research/divide-and-prosper-why-firms-divide-prices-instead-charging-single-price'),'ドリップ価格は段階的開示を伴う別の側面。単純同義語にはしない。'),
  r(81,'behavioral-science-d','スノッブ効果',['snob effect'],'phenomenon',
    '他の人が多く持つことにより、その品の魅力や需要が下がること。珍しい品を選んだ人が、広く普及すると別の品へ移る場合などが例になる。他者との差別化が価値に含まれる選択を理解する手掛かりになる。希少な物を好む理由がすべてスノッブ効果とは限らず、実際の品質や利用価値も区別する。価格が高いこと自体を地位の表示として求めるヴェブレン効果や、流行に合わせるバンドワゴン効果とは説明する方向が異なる。',['kb_729','kb_514','kb_107'],s('Harvey Leibenstein',"Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)",'https://academic.oup.com/qje/article-abstract/64/2/183/1931945'),'他者の消費量との関係を扱う需要の概念。'),
  r(82,'behavioral-science-d','ヴェブレン効果',['Veblen effect','ベブレン効果'],'phenomenon',
    '高い価格が地位や富の表示として価値をもち、価格の高さが需要を支えること。品質が同じでも、高価だと周囲に伝わる品が選ばれる場合などを考える。消費の理由を振り返る際、実際の使い勝手と地位の表示としての価値を分けてみられる。高価な品を買う行動がすべてこの効果ではなく、品質や希少性への評価とも区別する。値上げすれば必ず売れるという法則ではない。他者が持たないことを好むスノッブ効果とも異なる。',['kb_107','kb_474','kb_514'],s('Harvey Leibenstein；Thorstein Veblenの顕示的消費に由来',"Bandwagon, Snob, and Veblen Effects in the Theory of Consumers’ Demand (1950)",'https://academic.oup.com/qje/article-abstract/64/2/183/1931945'),'顕示的消費はより広い概念なので正式同義語へ入れない。'),
  r(87,'behavioral-science-d','ディスポジション効果',['disposition effect'],'phenomenon',
    '利益が出た資産は早く売り、損失が出た資産は長く持ち続ける傾向。利益を確定する安心と、損失を認める抵抗が、現在の見込みとは別に判断へ入り込む場合がある。過去の取得価格への感情と、今後の判断根拠を分けて振り返る概念として使える。ただし税、手数料、資金需要、合理的な見通しによる売買もあり、個別の保有を直ちに誤りとは決められない。損失回避を資産の処分行動に適用した現象で、売買の推奨ルールではない。',['kb_134','kb_757','kb_273'],s('Hersh Shefrin / Meir Statman','The Disposition to Sell Winners Too Early and Ride Losers Too Long (1985)','https://doi.org/10.1111/j.1540-6261.1985.tb05002.x'),'現象の理解に限定し、特定資産の売買判断を勧めない。'),
  r(88,'behavioral-science-d','近視眼的損失回避',['myopic loss aversion'],'model',
    '損失を強く嫌う傾向と、結果を短い間隔で評価することが組み合わさり、長期とは異なるリスク判断になるという説明。変動する成果を毎日確かめると、小さな下落を何度も経験して慎重になりやすい場合などを考える。評価頻度が自分の反応にどう影響するかを振り返る手掛かりになる。長く見ればどんなリスクも安全になるという意味ではなく、必要な監視を減らす指示でもない。現在の利益を優先する現在バイアスとは機序が異なる。',['kb_134','kb_175'],s('Shlomo Benartzi / Richard H. Thaler','Myopic Loss Aversion and the Equity Premium Puzzle (1995)','https://doi.org/10.2307/2118511'),'評価間隔と損失回避の組合せ。長期投資の効能保証ではない。'),
  r(89,'behavioral-science-d','確率マッチング',['probability matching'],'phenomenon',
    '起こる結果の頻度に合わせて、予測や選択の割合を配分する傾向。独立に赤が7割出る課題で、赤を7割、青を3割予測するような例である。正答数だけを最大化するなら毎回赤を選ぶ方が有利な設定でも、割合を合わせる行動が見られる。確率的な選択を点検する際、目的が予測の的中、探索、分配のどれかを明確にする。環境が変わる場合や探索に価値がある場合を含め、すべての確率的選択を非合理とはしない。',['kb_755','kb_713','kb_287'],s('Nir Vulkan','An Economist’s Perspective on Probability Matching (2000)','https://doi.org/10.1111/1467-6419.00106'),'強化率と行動配分のマッチング法則とは別概念。'),
  r(90,'behavioral-science-m','意図と行動のギャップ',['intention-behavior gap','intention–behaviour gap'],'phenomenon',
    '行うつもりがあることと、実際に実行することの間に隔たりがあること。運動しようと決めても、時間や場所を決めず、仕事後には始められない場合などがある。意欲を高めるだけでなく、機会、手順、障害、思い出すきっかけまで確かめる必要を示す。実行意図や環境の調整を検討する入口になるが、ギャップ自体は一つの原因を指さない。実行できなかった人を無責任と評価する名称ではなく、資源や機会の制約も含めて考える。',['kb_172','kb_181','kb_167'],s('Paschal Sheeran','Intention–Behavior Relations: A Conceptual and Empirical Review (2002)','https://doi.org/10.1080/14792772143000003'),'理論名ではなく観察される隔たりの概念。'),
  r(93,'behavioral-science-m','計画的行動理論',['theory of planned behavior','theory of planned behaviour'],'theory',
    '行動への態度、周囲が期待していると感じる規範、自分に実行できるという認識が意図を形成し、意図と実際の統制可能性が行動に関わるとする理論。研修への参加を考えるなら、有益と思うか、周囲の期待、時間や手段の確保を分けて尋ねられる。計画は立てたのに実行しない理由を整理する枠組みになる。ただし意図だけで行動は決まらず、習慣、感情、制度的制約もある。全行動を精密に予測する式として使わない。',['kb_169','kb_172','kb_455'],s('Icek Ajzen','The theory of planned behavior (1991)','https://doi.org/10.1016/0749-5978(91)90020-T'),'TPBは補助語。実際の統制と知覚された統制を区別。'),
  r(96,'behavioral-science-h','習慣不連続性仮説',['habit discontinuity hypothesis'],'theory',
    '引っ越しや転職などで行動の手掛かりとなる状況が変わると、古い習慣の自動的な実行が弱まり、行動を見直す機会が生まれるという仮説。通勤経路が変わったときに移動手段を選び直す場合などが例になる。生活の移行期には、望む行動を実行しやすい手順や物の配置を早めに作るとよい。変化だけで良い習慣が自然に身につくわけではなく、新しい機会や支援が必要である。継続が途切れた人の意欲不足を意味しない。',['kb_535','kb_180','kb_184'],s('Bas Verplanken / Deborah Roy','Empowering interventions to promote sustainable lifestyles (2016)','https://www.sciencedirect.com/science/article/pii/S0272494415300487'),'状況変化を活かした介入の検討。新鮮なスタートの心理的区切りとは異なる。'),
  r(97,'behavioral-science-h','行動の波及効果',['behavioral spillover','behavioural spillover'],'phenomenon',
    '一つの行動やそれを促す介入が、直接は対象としていなかった別の行動にも影響すること。節電を始めて他の省資源行動も増える場合もあれば、良いことをした安心から別の消費が増える場合もある。施策の評価では狙った行動だけでなく、隣接する行動への正負の影響も確認する。二つの行動が一緒に起きたという相関だけでは波及とは言えない。モラル・ライセンシングは負の波及を説明しうる一つの機序で、全体の同義語ではない。',['kb_883','kb_443','kb_180'],s('Paul Dolan / Matteo M. Galizzi','Like ripples on a pond: Behavioral spillovers and their implications (2015)','https://researchonline.lse.ac.uk/id/eprint/60804/1/__lse.ac.uk_storage_LIBRARY_Secondary_libfile_shared_repository_Content_Dolan%2C%20P_Like%20ripples_Dolan_Like%20ripples_2015.pdf'),'正負の双方を扱う。単なる行動の共起と因果的な波及を区別。'),
  r(99,'behavioral-science-h','社会規範フィードバック',['social norms feedback','normative feedback'],'method',
    '自分の行動を、関連する集団の実際の行動や望ましい基準と比較して伝える方法。電力使用量を近い条件の世帯と比べて示すことなどが例になる。介入では比較対象を適切に選び、実際の分布を正確に伝える。平均より良い行動をしていた人が平均へ戻る逆効果もあるため、望ましい行動への承認を組み合わせるなど設計が必要になる。単に「皆がやっている」と圧力をかける方法ではなく、効果の方向を測定して確かめる技法である。',['kb_455','kb_266','kb_179'],s('P. Wesley Schultzほか','The constructive, destructive, and reconstructive power of social norms (2007)','https://pubmed.ncbi.nlm.nih.gov/17576283/'),'記述的規範と命令的規範の相互作用、ブーメラン効果を含める。'),
  r(102,'behavioral-science-l','行動形成（シェイピング）',['shaping','逐次接近法'],'method',
    '目標行動に少しずつ近づく反応を選んで強化し、まだできない行動を形成する学習手続き。発表練習なら、まず短く声に出すこと、次に要点を伝えることへと、達成基準を段階的に上げる。現在の行動、次の小さな基準、強化するタイミングを具体化して使う。作業を分割するだけではシェイピングとは限らず、結果に応じた強化の条件が重要である。急に基準を上げたり、相手が望まない目標へ誘導したりしない。',['kb_536','kb_437','kb_529'],s('B. F. Skinner；OpenStax（参照教材）','Psychology 2e, 6.3 Operant Conditioning','https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning'),'習慣設計にも使えるが、機序に合わせ学習・強化へ配置。'),
  r(104,'behavioral-science-h','COM-Bモデル',['COM-B model','COM-B'],'model',
    '行動の成立を、能力、機会、動機の相互作用として捉えるモデル。実行しない人に意欲を求める前に、方法を知っているか、必要な場所や道具があるか、習慣や感情がどう関わるかを分けて調べる。例えば研修後に手順を使わない場合、知識不足と時間不足では支援が異なる。介入を選ぶ前の問題整理に使えるが、三項目を埋めるだけで効果が保証されるわけではない。本人の希望、環境の制約、実際の結果を確かめながら設計する。',['kb_943','kb_944','kb_181','kb_169'],s('Susan Michie / Maartje M. van Stralen / Robert West','The behaviour change wheel (2011)','https://pmc.ncbi.nlm.nih.gov/articles/PMC3096582/'),'COM-Bは行動変容の輪の中心モデル。BCW全体を正式別名にしない。'),
  r(106,'behavioral-science-h','EASTフレームワーク',['EAST framework','EAST'],'method',
    '行動を促す設計を、簡単に、魅力的に、社会的に、適切な時に、という四つの観点で点検する実践枠組み。提出を増やしたいなら入力工程を減らし、要点を目立たせ、適切な規範情報を伝え、準備できる時点で案内する。施策の案出に使い、その後は比較や実験で結果を確かめる。人を必ず動かす四法則ではなく、対象や状況で有効性は変わる。誤った社会情報や、本人の選択を妨げる誘導を正当化しない。',['kb_179','kb_178','kb_181'],s('Behavioural Insights Team','EAST: Four simple ways to apply behavioural insights (2014；改訂版あり)','https://www.bi.team/publications/east-four-simple-ways-to-apply-behavioural-insights/'),'学術的な単一理論ではなく設計の実践枠組み。'),
  r(110,'behavioral-science-h','健康信念モデル',['health belief model'],'model',
    '健康に関わる行動を、問題が自分に起こる可能性や重大さ、行動の利益と障壁、きっかけなどの認識から理解するモデル。健診を勧める場合、必要性を理解していないのか、費用や時間が障害なのかを分けて聞く。恐ろしさだけを強調せず、実行できる選択肢を確かめる手掛かりになる。後の拡張では自己効力感なども考慮する。信念だけで行動が決まるとは限らず、医療へのアクセスや制度の制約もある。個別の診断や治療判断に代わるものではない。',['kb_169','kb_228','kb_181'],s('Irwin M. Rosenstock','Historical Origins of the Health Belief Model (1974)','https://doi.org/10.1177/109019817400200403'),'健康行動の説明モデル。一般場面への例は応用であり医療的効能を示さない。'),
  r(111,'behavioral-science-h','保護動機理論',['protection motivation theory'],'theory',
    '脅威への評価と、対処できるかの評価が、防御的な行動の意図にどう関わるかを説明する理論。情報セキュリティの注意喚起では、被害の深刻さだけでなく、推奨行動の有効性や自分に実行できる感覚が重要になる。警告と具体的な対処手順を一緒に設計するために使える。後の拡張ではコストや報酬なども扱う。恐怖を強めるほど良いという理論ではなく、回避や否認が起きる可能性もある。意図と実行、知覚と実際の能力を分けて評価する。',['kb_169','kb_228','kb_207'],s('Ronald W. Rogers','A Protection Motivation Theory of Fear Appeals and Attitude Change (1975)','https://doi.org/10.1080/00223980.1975.9915803'),'1975年の原提案と後の拡張の違いを明記。'),
  r(112,'behavioral-science-h','健康行動プロセスアプローチ',['health action process approach','HAPA'],'model',
    '健康行動を始めようとする動機形成と、その後の計画、実行、維持、再開を分けて考える枠組み。運動したいと思う段階と、忙しい週にどう続けるかを決める段階では、必要な支援が違う。いつどこで行うかに加え、障害が出た際の対処や中断後の再開も具体化する。各段階で自己効力感の役割を考えるが、誰もが固定した順序を一度だけ進むわけではない。生活上の資源や本人の希望を確認し、モデルを治療手順や成果の保証として使わない。',['kb_944','kb_172','kb_169'],s('Ralf Schwarzer','Modeling Health Behavior Change (2008)','https://doi.org/10.1111/j.1464-0597.2007.00325.x'),'段階という語だけで行動変容ステージモデルへ統合しない。'),
  r(114,'behavioral-science-l','フィードバック介入理論',['feedback intervention theory'],'theory',
    '成績についての情報が、課題の処理、学び方、自己への注意のどこへ向けられるかによって、その後の成績が変わると考える理論。人格への評価ばかりを伝えると、作業の改善より自分を守ることへ注意が移る場合がある。指導では具体的な課題、目標との差、次に試す行動へ焦点を合わせ、結果を確かめる。フィードバックは必ず成績を高めるわけではない。理論は効果の違いを説明する枠組みで、唯一の正しい伝え方を決めるものではない。',['kb_394','kb_537','kb_167'],s('Avraham N. Kluger / Angelo DeNisi','The effects of feedback interventions on performance (1996)','https://doi.org/10.1037/0033-2909.119.2.254'),'メタ分析と理論提案。SBI等の手順そのものとは区別。'),
  r(115,'behavioral-science-d','投影バイアス',['projection bias'],'phenomenon',
    '現在の好みや身体状態が将来も続くと見積もり、将来の自分の選好の変化を十分に考慮できない傾向。空腹時に翌週の食料を買うと、後で必要な量より多く選ぶ場合などがある。先の予定や購入を決めるときは、今とは異なる状態でどう感じるかを具体的に想像し、過去の記録も確かめる。単に現在の利益を優先する現在バイアスとは違い、将来の好みの予測が対象になる。将来は今と必ず違うと決めつけるのではなく、変化の可能性を見積もる。',['kb_429','kb_234','kb_175'],s('George Loewenstein / Ted O’Donoghue / Matthew Rabin','Projection Bias in Predicting Future Utility (2003)','https://doi.org/10.1162/003355303322552784'),'ホット・コールド共感ギャップと接点があるが、将来選好への投影に焦点を置く。'),
  r(116,'behavioral-science-d','認識ヒューリスティック',['recognition heuristic','再認ヒューリスティック'],'heuristic',
    '二つの対象の一方だけを知っている場合、その知っている方がある基準で大きいと推測する簡便な方略。二都市の人口を比べる際、名前を聞いたことのある都市を選ぶような例である。知っているかどうかが対象の基準と相関する環境では有効な場合がある。聞き覚えを根拠にした判断では、その相関が今の環境にあるかを確かめる。広告で知られた品など、知名度が品質と結び付かない場面では外れうる。再認主導意思決定モデルとは異なる。',['kb_597','kb_825','kb_754'],s('Daniel G. Goldstein / Gerd Gigerenzer','Models of Ecological Rationality: The Recognition Heuristic (2002)','https://doi.org/10.1037/0033-295X.109.1.75'),'recognition-primed decisionと同義にしない。'),
  r(117,'behavioral-science-d','Take-the-bestヒューリスティック',['take-the-best heuristic'],'heuristic',
    '予測力の高い手掛かりから順に二候補を比べ、最初に差がついた手掛かりだけで判断を止める方略。どちらの都市が大きいかを考えるとき、重要と見積もる特徴から調べ、区別できた段階で選ぶ。すべての情報を合計せずとも、不確実な環境では良い予測になる場合がある。手掛かりの順序や環境構造に依存するため、重要な条件を無視してよいという勧めではない。必須条件の確認や、安全に関わる判断には別の点検が必要になる。',['kb_754','kb_277','kb_597'],s('Gerd Gigerenzer / Daniel G. Goldstein','Reasoning the fast and frugal way (1996)','https://doi.org/10.1037/0033-295X.103.4.650'),'二候補間での識別と停止のルール。一般的な最善選択の意味ではない。'),
  r(118,'behavioral-science-d','側面ごとの消去法',['elimination by aspects'],'model',
    '選択肢のある側面に着目し、その側面を満たさない候補を除く過程を繰り返す選択モデル。住まいを選ぶ際、通勤時間、費用、設備などで候補を順次絞る場合が身近な例になる。原モデルでは側面が重みに応じて確率的に選ばれる点を含む。実務では除外条件を明示する手掛かりになるが、条件の順序で残る候補が変わる可能性を確かめる。全属性の得点を足す方法や、最初の差で二候補を選ぶTake-the-bestとは異なる。',['kb_277','kb_275','kb_754'],s('Amos Tversky','Elimination by aspects: A theory of choice (1972)','https://doi.org/10.1037/h0032955'),'日本語の手順例と、原著の確率的モデルを区別する。'),
  r(121,'behavioral-science-d','スラッジ',['sludge'],'model',
    '必要な行動を妨げる過大な手間、分かりにくさ、待ち時間などの摩擦を点検する概念。申請に何度も同じ情報を入力させる、解約方法が見つからないといった状況で、形式上の選択肢があっても利用しにくくなる。改善では工程や負担を可視化し、目的に比べ不要な障壁を減らす。本人を助ける確認手順まで無条件に取り除く意味ではない。ナッジの単なる反対語ではなく、利益、必要性、分配の不公平も検討して摩擦を評価する。',['kb_181','kb_178','kb_179'],s('Cass R. Sunstein','Sludge Audits (2020)','https://doi.org/10.1017/bpp.2019.32'),'行動摩擦一般のうち過大・不必要な負担を評価する規範的観点。'),
  r(128,'behavioral-science-d','不平等回避',['inequity aversion'],'model',
    '自分と他者の取り分の不平等が、不利益でも有利でも効用に影響すると捉える社会的選好のモデル。自分の取り分が増えても極端に不公平な分配を拒んだり、自分の利益を減らして差を縮めたりする行動を考える。交渉や分配では総額だけでなく、誰とどう比べられているかを確かめる視点になる。人は全員同じ平等を求めるわけではなく、貢献、手続き、関係によっても反応は変わる。すべての協力や公正判断を説明する唯一の理論ではない。',['kb_031','kb_768','kb_798'],s('Ernst Fehr / Klaus M. Schmidt','A Theory of Fairness, Competition, and Cooperation (1999)','https://doi.org/10.1162/003355399556151'),'inequity aversionのモデルを中心に説明。分配的公正全体の同義ではない。'),
  r(129,'behavioral-science-d','生態学的合理性',['ecological rationality'],'theory',
    '判断方略の良し悪しを、形式的に複雑かどうかだけでなく、用いる環境の情報構造との適合で評価する立場。少数の確かな手掛かりで判断する方法が、データが少ない場面では複雑な計算よりよい予測になる場合がある。方略を選ぶ際、利用できる情報、ノイズ、時間、目的を確かめる。単純な直感はいつでも優れるという主張ではなく、どの条件でどの方略が役立つかを検証する。環境保護の行動を合理的と呼ぶ意味とは異なる。',['kb_754','kb_287','kb_277'],s('Gerd Gigerenzerほか','Ecological rationality: Rethinking behavioural economics（著者公開資料）','https://pure.mpg.de/pubman/item/item_3492412_12'),'認識・Take-the-bestは個別方略。本カードは環境適合の評価枠組み。'),
  r(130,'practical-wisdom-c','PREP法',['PREP method'],'method',
    '結論、理由、具体例、結論の順で短い説明を組み立てる型。会議で案を勧めるなら、まず案を述べ、その理由、具体的な利用場面を示し、最後に要点へ戻る。話す前に四項目を一行ずつ書くと、主張と根拠のつながりを点検できる。例を出すだけで証拠になったと思わず、相手の疑問に応じて資料を補う。物語、探索的な対話、緊急連絡など、別の順序が適する場面もある。学術的な説得効果や万能な話術を証明した理論ではない。',['kb_394','kb_407'],s('愛知工業大学キャリアセンター（参照教材）','就職活動ハンドブック2025：相手に伝わる内容にしよう','https://www.aitech.ac.jp/assets/docs/career/for-students/center_for-students_handbook2025.pdf'),'実務上の構成技法。由来や単一の発明者は断定しない。'),
  r(132,'practical-wisdom-c','SBAR法',['SBAR','situation-background-assessment-recommendation'],'method',
    '状況、背景、評価、提案または依頼を分けて伝える連絡の型。障害報告なら、今起きていること、直前の変更、把握した原因候補、相手に求める対応を順に示す。医療のチーム連絡で使われる方法を一般業務へ応用した例である。事実と自分の評価を区別し、必要な情報がそろったか確認して使う。引き継ぎ全体や緊急対応の専門手順を置き換えるものではなく、聞き手の質問と理解の確認も必要になる。',['kb_435','kb_777'],s('Agency for Healthcare Research and Quality','TeamSTEPPS: SBAR','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/sbar.html'),'医療発祥の連絡技法。一般業務の例は翻案。'),
  r(133,'practical-wisdom-c','アイ・メッセージ',['I-message','I-messages','私メッセージ'],'method',
    '相手の人格を評価する言い方を避け、自分が見た行動、それが及ぼす影響、自分の感じ方や必要を伝える方法。「あなたは無責任」ではなく「予定が直前に変わると準備できず困る」と具体的に述べる。事前に事実と評価を分け、伝えた後は相手の事情も聞く。主語を私にするだけで非難が消えるわけではなく、「私はあなたが悪いと思う」は実質的に評価のままである。深刻な権力差や危険な関係では、この話し方だけで解決を期待しない。',['kb_008','kb_404','kb_092'],s('Thomas Gordon / Gordon Training International','Origins of the Gordon Model','https://www.gordontraining.com/thomas-gordon/origins-of-the-gordon-model/'),'Gordonの方法を参照。相手の同意を得る保証や感情の押し付けの道具ではない。'),
  r(134,'practical-wisdom-c','SBIフィードバック',['SBI feedback','situation-behavior-impact'],'method',
    '特定の状況、その場で観察した行動、その影響の三点でフィードバックする技法。「今朝の打合せで、説明中に何度も質問が重なり、最後の確認ができなかった」のように具体化する。伝える前に日時や場面を確かめ、行動と推測した意図を分ける。本人の意図を聞くこともできるが、意図が良ければ影響が消えるわけではない。人格評価や一方的な断罪を避ける補助であり、三点を述べれば必ず相手が納得するというものではない。',['kb_394','kb_045','kb_424'],s('Center for Creative Leadership','Situation–Behavior–Impact feedback（開発元の解説）','https://www.ccl.org/articles/leading-effectively-articles/closing-the-gap-between-intent-vs-impact-sbii/'),'開発元の定義を参照。効果の宣伝表現は採用しない。'),
  r(136,'practical-wisdom-c','動機づけ面接',['motivational interviewing'],'method',
    '変化について迷いがある人と、協働し、本人の理由や価値を引き出しながら話す面接の方法。始めたい気持ちと続ける不安の両方を聞き、本人がどうしたいかを確かめる。開かれた質問、是認、聞き返し、要約などを、相手の自律性を尊重する姿勢とともに使う。こちらの望む方向へ巧みに誘導する質問集ではない。専門的実践には学習と訓練が必要で、一般の会話での応用が治療と同じ効果をもつとは限らない。',['kb_404','kb_520','kb_050'],s('William R. Miller / Stephen Rollnick；MINT','Understanding Motivational Interviewing','https://motivationalinterviewing.org/understanding-motivational-interviewing'),'共同的な姿勢とプロセスを重視。医療・心理支援の代替として提示しない。'),
  r(137,'practical-wisdom-c','ティーチバック法',['teach-back','teach-back method'],'method',
    '説明した内容を相手自身の言葉で述べてもらい、こちらの伝え方が十分だったかを確かめる方法。新しい手順を伝えた後、「説明が分かりにくくなかったか確認したいので、次にすることを教えてください」と頼む。理解が違っていれば説明を変え、もう一度確認する。相手の知識を試す試験や、原文を暗唱させる方法ではない。医療での利用を一般業務へ応用する場合も、相手を責めない言い方と、説明する側の責任を明確にする。',['kb_828','kb_748','kb_777'],s('Agency for Healthcare Research and Quality','TeamSTEPPS: Teach-Back','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/teachback.html'),'プロテジェ効果は教える側の学習効果。理解確認の本手法とは同義にしない。'),
  r(138,'practical-wisdom-c','クローズドループ・コミュニケーション',['closed-loop communication'],'method',
    '送り手が情報を伝え、受け手が受領内容を返し、送り手がそれを確かめることで連絡の輪を閉じる方法。作業依頼なら「Aを15時までに」へ受け手が内容を返し、送り手が一致を確認する。重要な数値や役割を伝えるときに、確認する情報を絞って使う。受け手がうなずいただけでは、同じ理解になったかは分からない。確認の負担と重要度を考慮し、通常の対話をすべて機械的な復唱にしない。専門現場では既定の手順を優先する。',['kb_777','kb_435','kb_487'],s('Agency for Healthcare Research and Quality','TeamSTEPPS: Closed-Loop Communication','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/loop.html'),'Check-Backは輪を閉じる具体的手続き。完全な同義語とはせず補助語へ。'),
  r(139,'practical-wisdom-c','STAR法',['STAR method','situation-task-action-result'],'method',
    '状況、課題、自分の行動、結果の順で経験を説明する型。面接で「調整が得意」と述べる代わりに、期限が重なった状況、担当した課題、行った調整、その結果を具体的に話す。準備では各項目を書き、チームの成果と自分の行動を分け、結果に不確実さがあれば明示する。全ての経験を成功談へ整える必要はなく、失敗から学んだ点も説明できる。説得力のための構成技法であり、結果だけから行動の質が証明されるわけではない。',['kb_722','kb_117','kb_394'],s('National Careers Service','The STAR method','https://nationalcareers.service.gov.uk/careers-advice/interview-advice/the-star-method'),'TeamSTEPPSのSTAR安全確認とは別の同名略語。STAR単独は補助語として扱う。'),
  r(140,'practical-wisdom-c','SCQA',['SCQA framework','situation-complication-question-answer'],'method',
    '共有できる状況、そこに生じた変化や問題、答えるべき問い、答えの順で説明を組み立てる型。提案書なら、現状の運用、増えた負担、何を変えるべきか、提案という流れにする。相手が何を既に知り、どの問いに答えてほしいかを確認してから使う。問題を大げさに作って提案を正当化せず、状況と根拠を照合する。Mintoの文章構造の考え方に沿う実務技法であり、探索中の議論や感情の共有には別の構成が適する場合もある。',['kb_407','kb_498'],s('Barbara Minto','The Minto Pyramid Principle（著者の公式解説）','https://barbaraminto.com/'),'SCQAの構成と、ピラミッド原則全体を同義にしない。'),
  r(141,'practical-wisdom-c','SPIN話法',['SPIN selling','SPIN questioning'],'method',
    '状況、問題、その問題の影響、解決による価値を尋ねる質問の枠組み。業務の相談なら現在の手順を聞き、困る点、その影響、改善できた場合の意味を相手と確かめる。単に質問を順番に読み上げず、既に分かる状況は調べ、必要な問いに絞る。営業研究からの方法だが、どの商談にも同じ順序や成果が保証されるわけではない。相手の不安を意図的に増幅したり、合わない提案へ誘導したりするために使わない。',['kb_407','kb_148','kb_149'],s('Neil Rackham / Huthwaite International','The SPIN Methodology','https://www.huthwaiteinternational.com/spin-methodology'),'開発元の質問分類を参照。販売成功率等の宣伝上の断定は本文へ取り込まない。'),
  r('extra-ipass','practical-wisdom-c','I-PASS',['I-PASS handoff'],'method',
    '重症度、患者の要約、実施事項、状況認識と対応計画、受け手による要約を整理する医療の引き継ぎの型。一般業務へ翻案するなら、緊急度、現状、次の作業、起こりうる問題と対処、受け手の理解確認に置き換えて考える。担当交代の前に未完事項と条件付きの対応を明文化し、最後に受け手が要点を返す。一般業務の翻案が医療と同じ成果を保証するわけではない。医療での利用は所属機関の正式な手順と訓練に従う。',['kb_777','kb_435','kb_487'],s('Agency for Healthcare Research and Quality / I-PASSの開発チーム','TeamSTEPPS: I-PASS','https://www.ahrq.gov/teamstepps-program/curriculum/communication/tools/ipass.html'),'医療原型と一般業務への翻案を区別。SBARは連絡構造、I-PASSは引き継ぎの型として別カード。'),
  r(145,'practical-wisdom-j','アイゼンハワー・マトリクス',['Eisenhower matrix','重要度・緊急度マトリクス'],'method',
    '仕事を重要度と緊急度の二軸で分け、すぐ行う、予定する、任せる、減らすなどの対応を考える整理法。締切の近い依頼に追われるとき、将来の準備や予防の時間が押し出されていないかを確かめられる。まず仕事を書き出し、目的への寄与と期限を別々に評価して使う。二軸の判断は主観や役割に依存するため、他者と重要度をすり合わせる。緊急でないことが不要という意味ではなく、図に分けるだけで仕事量や権限の問題が解決するわけではない。',['kb_483','kb_544','kb_192'],s('Stephen R. Covey / FranklinCovey（重要・緊急の実践整理）','The 5 Choices: Act on the Important','https://www.franklincovey.com/the-5-choices/choice-1/'),'通称と普及経路を区別し、Eisenhower本人が四象限を発明したとは断定しない。'),
  r(146,'practical-wisdom-j','なぜなぜ分析（5 Whys）',['5 Whys','five whys','なぜなぜ分析'],'method',
    '起きた問題について「なぜ」を重ね、表面的な事象から対処可能な原因へ掘り下げる方法。納期遅れを個人の不注意で止めず、確認の工程や情報の渡し方まで調べる。各答えを事実や現場の確認で支え、次の問いとの因果を確かめて使う。「五回」は厳密な回数規則ではない。原因が複数に分かれる問題もあり、一筋の物語で全体を説明しない。人を責める尋問や、都合のよい根本原因を想像する道具にせず、対策後の変化も検証する。',['kb_933','kb_932','kb_197'],s('大野耐一らのトヨタ生産方式；Lean Enterprise Institute','5 Whys','https://www.lean.org/lexicon-terms/5-whys/'),'原因仮説の作成と因果の検証を区別する。'),
  r(147,'practical-wisdom-j','ロジックツリー',['logic tree','issue tree','イシューツリー'],'method',
    '大きな問いを、調べられる小さな論点や要因へ枝分かれさせて整理する方法。売上の問題を客数と単価に分け、さらに各要因を調べると、何を検証すべきか見えやすくなる。まず答える問いを明確にし、分け方の基準を揃え、枝同士の関係を確かめる。整理した図は因果関係の証明ではなく、重要な要因を仮に配置したものにすぎない。データに応じて枝を修正し、細かく分けること自体を目的にしない。',['kb_933','kb_498','kb_561'],s('McKinsey & Company','How to master the seven-step problem-solving process','https://www.mckinsey.com/capabilities/strategy-and-corporate-finance/our-insights/how-to-master-the-seven-step-problem-solving-process'),'論点の分解技法。MECEは分け方の点検原則で別カード。'),
  r(148,'practical-wisdom-j','MECE',['mutually exclusive collectively exhaustive','ミーシー'],'principle',
    '対象を分ける際、区分の重なりを避け、必要な範囲の抜けも避けるという点検原則。顧客を地域で分ける場合に、一人が二地域へ二重計上されず、対象外の地域が抜けないようにする。最初に対象範囲と区分基準を決め、境界の事例を試す。実社会には複数の区分が妥当な問題もあり、無理に完全な分類へ押し込むと意味を失う。図を整えるために事実を捨てず、探索段階では仮の分類として見直す。単独で正しい結論を生む理論ではない。',['kb_934','kb_498'],s('Barbara Minto / McKinsey & Company','MECE: I invented it, so I get to say how to pronounce it','https://www.mckinsey.com/alumni/news-and-events/global-news/alumni-news/barbara-minto-mece-i-invented-it-so-i-get-to-say-how-to-pronounce-it'),'分類原則の実務用語。哲学上の排中律そのものではない。'),
  r(149,'practical-wisdom-j','意思決定ジャーナル',['decision journal'],'method',
    '重要な判断の時点で、選択肢、根拠、予測、確信度、気分や条件を書き残し、後から結果と照合する実践。計画を選んだときに成功の条件と予想確率を記録し、数か月後に何が当たったかを振り返る。結果を知ってから理由を書き換える後知恵を点検するために使える。結果の良し悪しだけで判断過程を採点せず、当時得られた情報と偶然も考慮する。記録するだけで判断力が必ず上がるという実証法則ではなく、振り返りの質が重要である。',['kb_709','kb_722','kb_710'],s('Shane Parrish / Farnam Street','How a Decision Journal Changed the Way I make Decisions','https://fs.blog/decision-journal/'),'実践者の方法としての出典。学術理論や効果量は付与しない。'),
  r(150,'practical-wisdom-j','意思決定マトリクス',['decision matrix','選択マトリクス'],'method',
    '選択肢を複数の基準で並べ、必要なら重みを付けて比較する方法。仕事の候補を、費用、時間、学習機会などで比較する際に、何を重視したかを見える形にできる。まず必須条件を確かめ、基準と重みを選択前に決め、採点の理由を記す。重みを少し変えて順位が変わるかも確認する。数値化しても価値判断や不確実さは消えず、合計点が客観的な正解になるわけではない。基準の重複や、得点で相殺できない制約に注意する。',['kb_498','kb_756','kb_934'],s('American Society for Quality','Decision Matrix；The Quality Toolbox','https://asq.org/quality-resources/decision-matrix'),'Pugh matrixは一形態であり、一般的マトリクス全体の厳密な同義語にしない。'),
  r(153,'practical-wisdom-w','アフターアクションレビュー',['after-action review','AAR'],'method',
    '活動後に、予定していたこと、実際に起きたこと、その差の理由、次に維持・改善することを関係者で確認する振り返りの方法。イベント後なら、参加者数だけでなく、準備と運営で何が機能したかを具体的な記録と照合する。評価者の講評だけで終えず、参加者が事実を出し、次の行動と担当を決める。責任追及の場にすると情報が出にくくなる。米軍の学習手法を一般業務へ応用する例であり、軍事の専門手順や形式をそのまま要求するものではない。',['kb_506','kb_892','kb_402'],s('U.S. Army','FM 7-0 Appendix K: After Action Reviews','https://www.first.army.mil/Portals/102/FM%207-0%20Appendix%20K.pdf'),'実施後の対話・学習手法。報告書作成そのものと同一視しない。'),
  r(154,'practical-wisdom-w','KPT振り返り',['KPT retrospective','Keep Problem Try'],'method',
    '続けたいこと、問題、次に試すことの三つに分けて活動を振り返る方法。チームで一週間の作業を思い出し、うまくいった連絡はKeep、滞った確認はProblem、次週の短い確認会をTryとして整理する。具体的な出来事を出し、試すことに担当と見直す時点を付ける。問題の一覧を作るだけでなく、続ける行動も残す点が特徴になる。Tryを増やしすぎると実行できなくなるため絞る。単独の学術理論ではなく、議論を支える実務上の型である。',['kb_506','kb_537','kb_394'],s('東京都デジタルサービス局（参照実践資料）','BPR手法の活用とKPTによる振り返り','https://www.digitalservice.metro.tokyo.lg.jp/documents/d/digitalservice/bpr-ver2'),'実務での手順を確認。発明者・初出は断定しない。'),
  r(155,'practical-wisdom-w','RACIマトリクス',['RACI matrix','RACI chart','RACI'],'method',
    '仕事ごとに、実行担当、最終的な説明責任をもつ人、相談先、情報共有先を整理する表。資料作成なら、書く人、承認する人、助言を求める人、完成を知らせる人を分けて合意する。曖昧な引き継ぎや承認待ちを見つけるため、作業と意思決定の単位を揃えて作る。表を作るだけで権限が発生するわけではなく、本人の認識、負荷、実際の承認ルールを確認する。相談先を増やしすぎず、変更時には更新する。職務上の権限や責任を勝手に変更する道具ではない。',['kb_487','kb_939','kb_497'],s('Project Management Institute','Roles, responsibilities, and resources (2008)','https://www.pmi.org/learning/library/best-practices-managing-people-quality-management-7012'),'RAMは上位の責任分担表一般。RACIと完全同義にしない。'),
  r(156,'practical-wisdom-w','ステークホルダーマップ',['stakeholder map','stakeholder mapping'],'method',
    '活動の影響を受ける人や関わる人を挙げ、関心、影響力、関係、必要な対話を整理する方法。新しい運用を導入するなら、決裁者だけでなく使う人や負担を受ける人も含める。二軸の図や関係図を使い、分からないことは本人への確認事項として残す。影響力の低い人を無視するための順位表ではない。分類は仮説なので、状況や意見の変化に応じて更新する。図を作るだけで合意が得られるわけではなく、実際の対話と意思決定が必要である。',['kb_081','kb_079','kb_487'],s('Association for Project Management','Communication planning (2020)','https://www.apm.org.uk/resources/whitepapers/communication-planning/'),'権力・関心の図は一形式。権利や被影響度を別に確認する。'),
  r(157,'practical-wisdom-w','PEST分析',['PEST analysis','PEST'],'method',
    '政治・制度、経済、社会、技術の四領域から、活動の外部環境を整理する方法。事業を考えるなら規制、費用、生活習慣、技術の変化を挙げ、それぞれがどう影響するかを検討する。情報の日付と根拠を記し、影響が大きく不確実な条件は複数の見通しに分ける。分類を埋めるだけでは将来予測にならず、因果や重要度も別に確かめる。法律と環境を分けるPESTLEなどの拡張もあるが、同じ項目を二重に数えたり、拡張全体を同義語にしたりしない。',['kb_908','kb_548','kb_593'],s('Chartered Institute of Personnel and Development','PESTLE analysis（PESTと拡張の説明）','https://www.cipd.org/en/knowledge/factsheets/pestle-analysis-factsheet/'),'外部環境の整理手法。PESTLE全体は拡張なので別名登録しない。'),
  r(158,'practical-wisdom-w','AIDAモデル',['AIDA model','AIDA'],'model',
    '注意、関心、欲求、行動の観点で広告や販売の働きかけを整理する古典的モデル。案内を見てもらえているのに申込みが少ない場合、内容への関心や必要性、手続きの障壁を分けて検討できる。各段階で何を伝え、どう確かめるかを明確にして使う。人が必ずこの順序だけで購入するという実証法則ではなく、比較、再訪、口コミなどで前後することもある。注意を集めたことと価値を提供したことを混同せず、誤解や過剰な欲求をあおる説明にしない。',['kb_400','kb_178','kb_781'],s('E. St. Elmo Lewisらに連なる広告・販売モデル；OpenStax','Principles of Marketing, 15.3 Steps in the Personal Selling Process','https://openstax.org/books/principles-marketing/pages/15-3-steps-in-the-personal-selling-process'),'歴史的な帰属は単純化しない。購入の固定的因果モデルにはしない。'),
  r(160,'practical-wisdom-w','JTBD',['jobs to be done','Jobs-to-be-Done'],'model',
    '人がある状況で成し遂げたい進歩を「ジョブ」として捉え、製品やサービスを選ぶ理由を理解する枠組み。移動中の朝食を選ぶ人なら、栄養だけでなく、手を汚さず移動時間を過ごす必要が関わる場合がある。実際の選択の前後を聞き、状況、障害、代替手段を整理する。属性や機能の一覧を捨てる意味ではなく、それだけで説明しきれない理由を探す。ジョブは職務名のことではなく、面接からの解釈も仮説として行動や他の資料と照合する。',['kb_149','kb_593','kb_543'],s('Clayton Christensen / Bob Moestaほか；Christensen Institute','Jobs to Be Done Theory','https://www.christenseninstitute.org/theory/jobs-to-be-done/'),'複数の実践流派がある。特定の分析様式だけを唯一の定義にしない。'),
  r(161,'practical-wisdom-w','STP分析',['segmentation targeting positioning','STP'],'method',
    '市場や利用者を意味のある違いで分け、対象を選び、その対象にとってどの価値で比較されたいかを定める方法。講座を作るなら学習目的や制約で利用者を分け、対象を絞り、他の手段との違いを明確にする。分類は調査で確かめ、対象の需要と自分が提供できるものを照合する。人を固定した属性へ押し込めたり、選んだ市場なら必ず成功すると考えたりしない。売り手の希望だけで位置づけは決まらず、利用者の認識と競合も必要である。',['kb_908','kb_544','kb_593'],s('Philip Kotlerらのマーケティング実務；OpenStax（参照教材）','Principles of Marketing, 5.6 Product Positioning (STP model)','https://openstax.org/books/principles-marketing/pages/5-6-product-positioning'),'市場の区分・選択・位置づけを一体の手順として収録。'),
  r(162,'practical-wisdom-w','マーケティングの4P',['marketing mix 4Ps','4Ps of marketing'],'method',
    '製品、価格、流通、販促の四観点から、顧客へ価値を届ける施策の組合せを考える枠組み。良い教材を作っても、価格が合わず、入手方法が分かりにくければ利用されにくい。誰にどの価値を届けるかを先に決め、四項目が矛盾していないかを点検する。各項目を埋めれば売れるという公式ではなく、顧客の反応や費用を調べて見直す。サービス等では拡張モデルもあり、四項目だけで事業全体や顧客経験のすべてを説明しない。',['kb_908','kb_593','kb_178'],s('E. Jerome McCarthy；OpenStax（参照教材）','Principles of Marketing, 1.2 The Marketing Mix and the 4Ps','https://openstax.org/books/principles-marketing/pages/1-2-the-marketing-mix-and-the-4ps-of-marketing'),'marketing mix一般と四項目のモデルの範囲差を保つ。'),
  r(163,'practical-wisdom-w','カスタマージャーニーマップ',['customer journey map','customer journey mapping'],'method',
    '利用者が目的を達成する過程を、行動、考え、感情、接点などとともに時系列で可視化する方法。申込みの途中で離れる理由を探すなら、案内を知る前から利用後までの経験を調べ、困る地点を整理する。対象の人物と場面、現状か将来像か、調査済みか仮説かを明示して作る。社内の想像だけで利用者の事実としない。図の美しさより、証拠のある課題と次の検証を決めることを重視する。すべての人が同じ一本道を通るわけではない。',['kb_593','kb_498','kb_423'],s('Nielsen Norman Group / Sarah Gibbons','Journey Mapping 101','https://www.nngroup.com/articles/journey-mapping-101/'),'実務上の調査・可視化手法。作成元の直接解説に基づく。'),
  r(164,'practical-wisdom-a','SMART目標',['SMART goals','SMART objectives'],'method',
    '目標を具体性、測定可能性、担当や達成可能性、現実性や関連性、期限などの観点で明確にする型。曖昧な「説明を改善する」を、対象、達成の確かめ方、実行する人、期限を含む計画へ直す。原提案と後の普及形ではAやRの語が異なるため、チームで意味を揃える。数値にできることだけを重要視せず、目的と指標がずれていないかを確かめる。明確な目標を作る技法であり、現実的な資源や学習なしに達成を保証する理論ではない。',['kb_167','kb_193','kb_172'],s('George T. Doran','There’s a S.M.A.R.T. way to write management’s goals and objectives (1981), Management Review 70(11), 35–36','https://www.decisionskills.com/uploads/5/1/6/0/5160560/doran_1981_s.m.a.r.t-way-management-review.pdf'),'原提案はSpecific, Measurable, Assignable, Realistic, Time-related。後の別展開と混同しない。'),
  r(165,'practical-wisdom-a','GTD',['Getting Things Done'],'method',
    '気になる仕事を収集し、意味と次の行動を明確にし、整理し、定期的に見直して実行する個人の仕事管理法。頭に抱えた「企画」を、連絡する相手や作る資料などの具体的な次の行動へ変える。置き場所と見直す時点を決め、仕組みを信頼できる状態に保つことが重要になる。リストを増やすだけの方法ではなく、何を今はしないかも判断する。提唱者の実践手法であり、誰にでも同じ生産性や精神的効果が保証されるものではない。',['kb_577','kb_441','kb_531'],s('David Allen','Getting Things Done: Five Steps','https://gettingthingsdone.com/five-Steps/'),'手法の定義を開発元で確認。商標表記と一般的なタスク管理を区別。'),
  r(166,'practical-wisdom-a','ポモドーロ・テクニック',['Pomodoro Technique'],'method',
    '短い集中作業と休憩を一組として繰り返し、中断や見積もりも記録する時間管理法。代表的には25分作業し短く休む。着手する作業を一つ決め、タイマー中の割込みを記し、区切りで進み方を振り返る。集中のきっかけや作業量の把握には使えるが、25分が全員に最適な注意の周期という科学的法則ではない。会議、対人支援、深い集中などでは区切り方を調整する。休憩を削って回数を競う使い方にせず、作業の性質と体調を優先する。',['kb_547','kb_192','kb_529'],s('Francesco Cirillo','The Pomodoro Technique（開発者の解説）','https://www.pomodorotechnique.com/'),'一般的なタイムボックスへ、集中・休憩の周期と中断管理を加えた特定手法。'),
  r(167,'practical-wisdom-a','タイムブロッキング',['time blocking','time-blocking'],'method',
    '予定表上に特定の仕事や活動を行う時間帯を割り当て、いつ取り組むかを先に決める方法。リストに「資料作成」と書くだけでなく、午前の一時間をその作業に確保する。移動や休息、予備時間も含めて組み、割込みがあれば計画を更新する。時間の枠を可視化するための技法で、予定を守れなかったことを失敗と採点するものではない。タイムボックスが作業に使う時間の上限へ着目するのに対し、予定の配置と実行機会の確保に焦点を当てる。',['kb_547','kb_172','kb_483'],s('Cal Newport（参照実践者）','Deep Habits: The Importance of Planning Every Minute of Your Work Day (2013)','https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/'),'実践者の直接解説。Newportが手法全体の発明者だとは主張しない。'),
  r(169,'practical-wisdom-a','SQ3R読書法',['SQ3R','SQ3R reading method'],'method',
    '全体を見渡す、問いを立てる、読む、見ずに説明する、振り返る、の五段階で学習用の文章を読む方法。章の見出しを問いへ変え、節を読んだ後に本を閉じて答え、答えられない部分を確かめる。読み流しを防ぎ、理解と想起を組み合わせるために使う。全ての文章へ同じ厳密な工程が必要なわけではなく、小説や速報を読む目的には調整できる。一度で完全に覚える保証はない。読む速さだけより、問いへ説明できるかを重視する。',['kb_199','kb_748','kb_744'],s('Francis P. Robinson；Texas A&M University（参照教材）','Reading Strategies: The SQ3R Method','https://asc.tamu.edu/tutoring/sq3r.html'),'Survey, Question, Read, Recite, Reviewの手順を確認。'),
  r(170,'practical-wisdom-a','コーネル式ノート',['Cornell note-taking system','Cornell notes'],'method',
    'ノートを記録、手掛かりや問い、要約の領域に分け、復習で説明し直すために使う方法。講義中に主な内容を記録し、後で問いを欄外へ書き、記録部分を隠して答える。最後に要点を自分の言葉でまとめ、間隔を置いて見直す。枠を引くこと自体より、問いと想起を組み合わせる点が重要になる。全ての授業や図解に同じ様式が適するとは限らず、内容に応じて変える。きれいに書き写しただけでは理解や長期記憶の保証にならない。',['kb_199','kb_200','kb_748'],s('Walter Pauk / Cornell University Learning Strategies Center','The Cornell Note-taking System','https://lsc.cornell.edu/notes.html'),'開発大学の教材を参照。用紙の体裁と学習活動を区別。'),
  r(171,'practical-wisdom-a','記憶の宮殿',['method of loci','memory palace','場所法'],'method',
    'よく知る場所の順序に、覚えたい情報を表すイメージを対応させ、場所をたどって取り出す記憶術。発表の要点を玄関、廊下、机へ順に置くイメージにして、発表時に道順から思い出す。まず安定した経路を選び、区別しやすい像を作り、実際に想起して確認する。練習により記憶課題を助ける研究があるが、理解、判断、全般的知能が一括して高まるとは言えない。情報量や使い回しによる混同にも注意する。',['kb_742','kb_743','kb_199'],s('Martin Dreslerほか','Mnemonic Training Reshapes Brain Networks to Support Superior Memory (2017)','https://pubmed.ncbi.nlm.nih.gov/28279356/'),'古典的な場所法の研究上の確認先。記憶競技の結果を一般能力へ拡大しない。'),
  r(173,'practical-wisdom-a','コンセプトマップ',['concept map','concept mapping','概念地図'],'method',
    '概念を線と関係語で結び、知識の構造を命題として表す学習・整理法。「注意は記憶の符号化に関わる」のように、二つの概念の間にどんな関係があるかを書く。中心となる問いを決め、概念を整理し、別の枝をまたぐ関係も検討する。単語を線でつなぐだけでは関係の意味が曖昧なため、自分の言葉で説明して点検する。自由な連想を広げるマインドマップとは目的や構造が異なる。図が複雑であることを理解の深さの証拠にしない。',['kb_414','kb_748','kb_746'],s('Joseph D. Novak / Alberto J. Cañas','The Theory Underlying Concept Maps and How to Construct and Use Them (2006/2008)','https://cmap.ihmc.us/publications/researchpapers/theoryunderlyingconceptmaps.pdf'),'概念間の命題と焦点質問を重視する手法。'),
  r(175,'practical-wisdom-s','思考記録表',['thought record','thought diary'],'method',
    '状況、感情、自動的に浮かんだ考え、その考えを支持する事実と反する事実、より釣り合った見方を記録する認知行動療法の技法。返信が遅いときに「嫌われた」と考えたなら、確認できる事実と推測を分け、他の説明を検討する。無理に前向きな結論へ変えず、感情の変化も確かめる。現実の危険や不公正を否定するために使わない。セルフヘルプには限界があり、苦痛が続く場合は本人に合う専門的な支援を検討する。',['kb_901','kb_573','kb_213'],s('NHS Every Mind Matters','Thought record CBT exercise','https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/thought-record/'),'記録技法をCBT全体の別名にはしない。'),
];

export const candidateDecisions = {
  16: {decision:'replace', replacement:'心的回転', reason:'頻度錯覚の通称の成立と、独立現象としての個別実証を今回の確認資料だけでは十分に結び付けられない。追加発見候補の実験的に同定できる心的回転へ置換。'},
};
